import sys
def compare_objects(obj1: object, obj2: object) -> dict[str, list]:
    differences = []
    common_attributes = set()
    if not isinstance(obj1, type):
        attributes_1 = dir(obj1)
    else:
        attributes_1 = obj1.__dict__.keys()
    if not isinstance(obj2, type):
        attributes_2 = dir(obj2)
    else:
        attributes_2 = obj2.__dict__.keys()
    all_attributes = set(attributes_1).union(set(attributes_2))
    for attr in sorted(all_attributes):
        try:
            val1 = getattr(obj1, attr, None) if not isinstance(obj1, type) else getattr(obj1, attr)
            val2 = getattr(obj2, attr, None) if not isinstance(obj2, type) else getattr(obj2, attr)
            is_different = (val1 != val2 or type(val1).__name__ != type(val2).__name__)
            common_attributes.add(attr)
            if is_different:
                differences.append({
                    'attribute': attr,
                    'object_1_value': str(val1),
                    'type_object_1': type(val1).__name__,
                    'object_2_value': str(val2),
                    'type_object_2': type(val2).__name__
                })
        except AttributeError:
            continue
    return {
        'common_attributes_count': len(common_attributes),
        'differences': differences,
        'memory_estimate_bytes': sys.getsizeof(obj1) + sys.getsizeof(obj2) if not isinstance(obj1, type) and not isinstance(obj2, type) else 0
    }
if __name__ == '__main__':
    class SampleClassA:
        def __init__(self):
            self.name = "Alpha"
            self.value = 42
    class SampleClassB:
        def __init__(self):
            self.name = "Beta"
            self.value = 100
            self.extra_field = True
    obj_a = SampleClassA()
    obj_b = SampleClassB()
    result = compare_objects(obj_a, obj_b)
    print(f"Common attributes count: {result['common_attributes_count']}")
    for diff in result['differences']:
        print(f"Difference at '{diff['attribute']}: 'Object A'={diff['object_1_value']} vs Object B'={diff['object_2_value']}'")
    if not isinstance(obj_a, type) and not isinstance(obj_b, type):
        estimated_memory = result['memory_estimate_bytes']
        print(f"Estimated combined memory usage: {estimated_memory} bytes")

import timeit
from typing import List, Tuple
def validate_input(data: List[int]) -> bool:
    return all(isinstance(x, int) for x in data) and len(data) > 0
class ComparisonEngine:
    def __init__(self):
        self.results = []
    def run_builtin_sort(self, data: List[int], iterations: int = 10) -> float:
        if not validate_input(data):
            raise ValueError("Input must be a non-empty list of integers.")
        setup_code = f"import timeit; d={data}"
        stmt = "timeit.timeit(stmt='d.sort()', setup=setup_code, number=iterations)"
        elapsed = timeit.default_timer()
        for _ in range(iterations):
            data_copy = list(data)
            data_copy.sort()
        total_time = timeit.default_timer() - elapsed
        return total_time / iterations
    def run_quicksort(self, data: List[int], iterations: int = 10) -> float:
        if not validate_input(data):
            raise ValueError("Input must be a non-empty list of integers.")
        setup_code = f"import timeit; d={data}"
        elapsed = timeit.default_timer()
        for _ in range(iterations):
            data_copy = list(data)
            self._quicksort_recursive(data_copy, 0, len(data_copy) - 1)
        total_time = timeit.default_timer() - elapsed
        return total_time / iterations
    def _quicksort_recursive(self, arr: List[int], low: int, high: int):
        if low < high:
            pi = self._partition(arr, low, high)
            self._quicksort_recursive(arr, low, pi - 1)
            self._quicksort_recursive(arr, pi + 1, high)
    def _partition(self, arr: List[int], low: int, high: int) -> int:
        pivot = arr[high]
        i = low - 1
        for j in range(low, high):
            if arr[j] <= pivot:
                i += 1
                arr[i], arr[j] = arr[j], arr[i]
        arr[i + 1], arr[high] = arr[high], arr[i + 1]
        return i + 1
if __name__ == '__main__':
    sample_data: List[int] = [64, 34, 25, 12, 22, 11, 90, 88, 76, 55, 44, 33, 22, 11, 10]
    engine = ComparisonEngine()
    builtin_time: float = engine.run_builtin_sort(sample_data)
    custom_time: float = engine.run_quicksort(sample_data)
    print(f"Builtin Sort Time (avg): {builtin_time:.6f}s")
    print(f"Custom Quicksort Time (avg): {custom_time:.6f}s")

import timeit
from typing import List, Tuple
class ComparisonEngine:
    def validate_input(self, list_a: List[int], list_b: List[int]) -> bool:
        if not isinstance(list_a, list) or not isinstance(list_b, list):
            return False
        try:
            [int(x) for x in list_a] + [int(x) for x in list_b]
            return True
        except ValueError:
            return False
    def sort_builtin(self, data: List[int]) -> None:
        data.sort()
    def run_comparison(self, test_data_1: List[int], test_data_2: List[int]) -> Tuple[float, float]:
        if not self.validate_input(test_data_1, test_data_2):
            raise ValueError("Input validation failed")
        iterations = 5000
        time_a = timeit.timeit(lambda: self.sort_builtin(list(test_data_1)), number=iterations)
        time_b = timeit.timeit(lambda: self.sort_builtin(list(test_data_2)), number=iterations)
        return time_a, time_b
if __name__ == '__main__':
    engine = ComparisonEngine()
    sample_list_integers = [543, 987, 102, 654, 321]
    sample_list_strings = ["apple", "banana", "cherry"]
    try:
        int_times = engine.run_comparison(sample_list_integers.copy(), sample_list_integers.copy())
        print(f"Integer Sort Times (A/B): {int_times[0]:.6f} / {int_times[1]:.6f}")
        str_times = engine.run_comparison(sample_list_strings, sample_list_strings)
        print(f"String Sort Times (A/B): {str_times[0]:.6f} / {str_times[1]:.6f}")
    except ValueError as e:
        print(e)

