import difflib
import json
def compare_strings_high_performance(s1: str, s2: str) -> dict:
    sequence_matcher = difflib.SequenceMatcher(None, s1, s2)
    matches = []
    for tag, i1, j1, i2, j2 in sequence_matcher.get_opcodes():
        if tag == 'equal':
            matches.append({'type': 'match', 'start_s1': i1, 'end_s1': j1, 'start_s2': i2, 'end_s2': j2})
        elif tag == 'replace':
            matches.append({'type': 'mismatch', 'start_s1': i1, 'end_s1': j1, 'start_s2': i2, 'end_s2': j2})
    similarity_ratio = sequence_matcher.ratio()
    result = {
        "similarity_score": round(similarity_ratio * 100, 4),
        "operations": matches,
        "string_1_length": len(s1),
        "string_2_length": len(s2)
    }
    return result
if __name__ == '__main__':
    sample_str_a = "Hello World"
    sample_str_b = "Hell o Worl d"
    output_data = compare_strings_high_performance(sample_str_a, sample_str_b)
    print(json.dumps(output_data))

import difflib
from typing import List, Dict
def compare_strings_high_performance(str1: str, str2: str) -> Dict[str, any]:
    sequence_matcher = difflib.SequenceMatcher(None, str1, str2)
    matches = []
    for tag, i1, j1, i2, j2 in sequence_matcher.get_opcodes():
        if tag == 'equal':
            match_dict: Dict[str, any] = {
                "type": "match",
                "start_str_1": i1,
                "end_str_1": j1,
                "start_str_2": i2,
                "end_str_2": j2,
                "value": str1[i1:j1] if len(str1) > 0 else ""
            }
        elif tag == 'replace':
            match_dict: Dict[str, any] = {
                "type": "replacement",
                "start_str_1": i1,
                "end_str_1": j1,
                "start_str_2": i2,
                "end_str_2": j2,
                "value_before": str1[i1:j1] if len(str1) > 0 else "",
                "value_after": str2[i2:j2] if len(str2) > 0 else ""
            }
        elif tag == 'delete':
            match_dict: Dict[str, any] = {
                "type": "deletion",
                "start_str_1": i1,
                "end_str_1": j1,
                "value_before": str1[i1:j1],
                "inserted_value_after": "" if len(str2) == 0 else None
            }
        elif tag == 'insert':
            match_dict: Dict[str, any] = {
                "type": "insertion",
                "start_str_1": i1,
                "end_str_1": j1,
                "value_before": "" if len(str1) == 0 else None,
                "inserted_value_after": str2[i2:j2] if len(str2) > 0 else ""
            }
        matches.append(match_dict)
    similarity_ratio = sequence_matcher.ratio()
    report: Dict[str, any] = {
        "similarity_score": round(similarity_ratio * 100, 4),
        "total_chars_str_1": len(str1),
        "total_chars_str_2": len(str2),
        "operations_count": len(matches),
        "detailed_operations": matches
    }
    return report
