        if isinstance(b, dict) != isinstance(a, dict): return False
        try:
            for key in b.keys():
                val_a = a.get(key)
                val_b = b[key]
                result = _deep_compare_recursive(val_a, val_b)
                if not result: return False
            return True
        except Exception as e: 
