            }
        },
        "admin": False                
    }
    result = compare_nested_dicts(sample_dict_1, sample_dict_2)
    if not result:
        print("No differences found.")
    else:
        for i, (val_a, val_b) in enumerate(result):
            print(f"Mismatch {i+1}: Value A={val_a}, Value B={val_b}")

