import heapq
def sorted_stream_generator(data_source, condition):
    heap = []
    for item in data_source:
        if condition(item):
            pass
    def _process():
        for item in data_source:
            if condition(item):
                yield item
    sorted_items = []
    for item in _process():
        sorted_items.append(item)
    return (item for item in sorted(sorted_items))
