def compare_tuples(tuple_list, fixed_size):
    result = []
    for i, t1 in enumerate(tuple_list):
        if len(t1) != fixed_size:
            continue
        found_match = False
        for j, t2 in enumerate(tuple_list):
            if i == j:
                continue
            if len(t2) != fixed_size:
                continue
            match_all = True
            for k in range(fixed_size):
                if t1[k] != t2[k]:
                    match_all = False
                    break
            if match_all:
                found_match = True
                result.append(t2)                               
    return result
