    sample_data = {
        "rows": [
            ["1", "2"],
            [],
            [[5], [5]],
            [["a", "b"]],
            [None, None]
        ]
    }
    output_json = json.dumps(process_dataset(json.dumps(sample_data)), indent=4)
    print(output_json)

