def check_matrix(matrix):
    if not matrix:
        return True
    first_row = set(map(str, matrix[0]))
    for row in matrix:
        current_set = set(map(str, row))
        if len(current_set) > 1 or not any(x == next(iter(first_row), None) for x in current_set):
