import heapq
from typing import Iterator
class StreamingMedianFinder:
    def __init__(self):
        self.max_heap = []                                                           
        self.min_heap = []                          
    def add_num(self, num: int) -> None:
        if not self.max_heap or num <= -self.max_heap[0]:
            heapq.heappush(self.max_heap, -num)
        else:
            heapq.heappush(self.min_heap, num)
        while len(self.max_heap) > len(self.min_heap) + 1:
            val = -heapq.heappop(self.max_heap)
            heapq.heappush(self.min_heap, val)
        while len(self.min_heap) > len(self.max_heap):
            val = heapq.heappop(self.min_heap)
            heapq.heappush(self.max_heap, -val)
    def find_median(self) -> float:
        if not self.max_heap and not self.min_heap:
            return 0.0
        mid_len = (len(self.max_heap) + len(self.min_heap)) // 2
        if len(self.max_heap) > len(self.min_heap):
            return -self.max_heap[0]
        median_val = (-self.max_heap[mid_len]) if self.max_heap else self.min_heap[mid_len]
        if len(self.max_heap) == 0 and len(self.min_heap) > 0:
            median_val = self.min_heap[0]
        total_len = len(self.max_heap) + len(self.min_heap)
        if total_len % 2 == 1:
            return float(median_val)
        else:
            left_mid_idx = (total_len // 2 - 1) if self.max_heap and not self.min_heap or len(self.max_heap) > len(self.min_heap) else total_len // 2 - 1
            val_left = float(-self.max_heap[0]) if self.max_heap else None
            val_right = float(self.min_heap[0]) if self.min_heap else None
            return (val_left + val_right) / 2.0
if __name__ == '__main__':
    stream_input = [5, 15, -3, 4, 6]
    finder = StreamingMedianFinder()
    for num in stream_input:
        finder.add_num(num)
    print(f"Current Median after processing {stream_input}:")
    median_val = finder.find_median()
    print(median_val)

import heapq
from typing import List, Iterator, Generator
class StreamingMedianProcessor:
    def __init__(self):
        self.min_heap = []
        self.max_heap = []                                                           
    def add(self, value: int) -> None:
        if not self.min_heap and not self.max_heap:
            heapq.heappush(self.max_heap, -value)
        elif len(self.max_heap) == len(self.min_heap):
            if -self.max_heap[0] < value:
                heapq.heapreplace(self.max_heap, -value)
            else:
                heapq.heappush(self.min_heap, value)
        else:
            if self.min_heap and value > self.min_heap[0]:
                heapq.heapreplace(self.min_heap, value)
            else:
                heapq.heappush(self.max_heap, -value)
    def get_median(self) -> float:
        total_len = len(self.min_heap) + len(self.max_heap)
        if total_len == 0:
            return None
        mid_idx = total_len // 2
        while not self.max_heap and self.min_heap:
            heapq.heappush(self.max_heap, -self.min_heap[0])
        if len(self.max_heap) > len(self.min_heap):
            return float(-self.max_heap[0])
        elif total_len % 2 == 1:
            return float(-self.max_heap[0])
        else:
            mid_min = self.min_heap[mid_idx]
            mid_max = -self.max_heap[mid_idx] if len(self.max_heap) > 0 else None
            while not self.max_heap and self.min_heap:
                heapq.heappush(self.max_heap, -self.min_heap[0])
            return (float(-self.max_heap[-1]) + float(mid_min)) / 2 if mid_max is None else (mid_max + mid_min) / 2
def process_stream(data_source: Iterator[int], output_interval: int = 5):
    processor = StreamingMedianProcessor()
    for i, value in enumerate(data_source):
        processor.add(value)
        if (i + 1) % output_interval == 0 or len(processor.min_heap) > 5:
            yield f"Current Median after {len(processor.max_heap) + len(processor.min_heap)} elements: {processor.get_median()}"
if __name__ == '__main__':
    stream_data = [12, 5, 8, 9, 7, 6, 4, 3, 10, 15, 2, 1]
    results = list(process_stream(iter(stream_data)))
    print("Streaming Median Results:")
    for result in results:
        print(result)

