def exists_optimized(items: list, target) -> bool:
    seen = set()
    for item in items:
        if item == target:
            return True
        elif isinstance(item, (list, dict)):
            try:
                hashable_item = tuple(sorted((type(item).__name__, str(item))))
            except TypeError:
                continue
            else:
                seen.add(hashable_item)
    for key in seen:
        if target == list(key)[0]:
            return True
    return False
