def reverse_any(seq):
    if isinstance(seq, str):
        return seq[::-1]
    elif hasattr(seq, '__reversed__'):
        return list(reversed(seq))
    else:
        try:
            return [x for x in reversed(list(seq))]
        except TypeError:
            print("Cannot reverse this sequence type.")
            return None
