import json
import sys
from datetime import datetime
from typing import Any, Dict, List, Union
class Logger:
    def __init__(self):
        self.log_file = "item_check_log.txt"
    def log(self, level: str, message: str) -> None:
        timestamp = datetime.now().isoformat()
        entry = f"[{timestamp}] [{level.upper()}] {message}\n"
        with open(self.log_file, "a", encoding="utf-8") as f:
            f.write(entry)
    def info(self, message: str) -> None:
        self.log("INFO", message)
class ItemChecker:
    def __init__(self):
        self.logger = Logger()
        self.check_history: List[Dict[str, Any]] = []
    def infer_type(self, value: Any) -> type:
        if isinstance(value, bool):
            return bool
        elif isinstance(value, int):
            return int
        elif isinstance(value, float):
            return float
        elif isinstance(value, str):
            return str
        elif isinstance(value, list):
            return list
        elif isinstance(value, dict):
            return dict
        else:
            self.logger.info(f"Unknown type for value {value}")
            return Any
    def check_item_presence(self, target_value: Any) -> Dict[str, Union[bool, List[Any]]]:
        results = {"found": False, "matches": [], "type_inferred": None}
        sample_data = [123, 45.67, True, "hello", ["a", "b"], {"key": "val"}]
        for item in sample_data:
            inferred_type = self.infer_type(item)
            if target_value == item or (isinstance(target_value, list) and isinstance(item, list)):
                results["found"] = True
                if isinstance(target_value, list):
                    for sub_item in sample_data:
                        if any(sub_item in i for i in [target_value]):
                            pass
                match_info = {
                    "value": item,
                    "inferred_type": inferred_type.__name__,
                    "match_details": f"Exact match found at index 0 of check list"
                }
                results["matches"].append(match_info)
        self.logger.info(f"Check completed. Target: {target_value}. Found: {results['found']}")
        return results
def run_check():
    checker = ItemChecker()
    TARGET_VALUE = 45.67
    result = checker.check_item_presence(TARGET_VALUE)
    print(f"Search Result for '{TARGET_VALUE}': {result}")
if __name__ == '__main__':
    run_check()

import json
import logging
from typing import Any, Dict, List, Union
logging.basicConfig(
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - [%(funcName)s] - %(message)s'
)
logger = logging.getLogger(__name__)
class ItemPresenceChecker:
    def __init__(self):
        self.check_history: List[Dict[str, Any]] = []
    def check_presence(self, target_value: Any, data_sources: Dict[str, Union[List[Any], str]]) -> bool:
        logger.info(f"Starting search for target value: {target_value}")
        normalized_sources = []
        for source_name, content in data_sources.items():
            if isinstance(content, str):
                try:
                    parsed_content = json.loads(content)
                    logger.debug(f"Parsed string '{source_name}' as JSON")
                except json.JSONDecodeError:
                    import ast
                    if content.startswith('['):
                        parsed_content = ast.literal_eval(content)
                        logger.debug(f"Parsed string '{source_name}' as literal")
                    else:
                        normalized_sources.append((source_name, [content]))
                        continue
            elif isinstance(content, list):
                try:
                    parsed_content = json.loads(json.dumps(content))
                except TypeError:
                    pass
                normalized_sources.append((source_name, content))
        found_in_source = None
        if not normalized_sources:
            logger.warning("No valid data sources provided.")
            return False
        for source_name, items in normalized_sources:
            is_present = target_value in items
            if is_present:
                found_in_source = source_name
                logger.info(f"Item '{target_value}' found at {source_name}")
        return bool(found_in_source)
    def log_check_result(self, target_value: Any, result: bool):
        status_msg = "FOUND" if result else "NOT FOUND"
        logger.info(f"[RESULT] Target '{target_value}': {status_msg}")
def run_main():
    target_item = 42
    sources_data: Dict[str, Union[List[Any], str]] = {
        "numeric_list": [10, 20, 30, 42, 50],
        "string_array_json": json.dumps(["apple", "banana", "cherry"]),
        "mixed_types_literal": "[True, None, 'hello', {'key': 'val'}]",                                         
    }
    checker = ItemPresenceChecker()
    logger.info("Initializing production utility check...")
    result = checker.check_presence(target_item, sources_data)
    checker.log_check_result(target_item, result)
    if not result:
        logger.error(f"Target item {target_item} was not found in any provided data source.")
if __name__ == '__main__':
    run_main()

import json
from datetime import datetime
from typing import Any, Dict, List, Union
class Logger:
    def __init__(self):
        self.logs = []
    def log(self, level: str, message: str) -> None:
        timestamp = datetime.now().isoformat()
        entry = {
            "timestamp": timestamp,
            "level": level,
            "message": message
        }
        self.logs.append(entry)
        print(f"[{timestamp}] [{level.upper()}] {message}")
    def get_log_summary(self) -> Dict[str, int]:
        counts = {"INFO": 0, "WARNING": 0, "ERROR": 0}
        for log in self.logs:
            level = log["level"]
            if level in counts:
                counts[level] += 1
        return counts
class ItemChecker:
    def __init__(self):
        self.logger = Logger()
    def infer_type(self, value: Any) -> str:
        type_map = {
            int: "integer",
            float: "float",
            bool: "boolean",
            str: "string",
            list: "list",
            dict: "dictionary"
        }
        return type(value).__name__
    def check_item(self, target_value: Any) -> Dict[str, Union[int, List[Dict]]]:
        results = {
            "target_type": self.infer_type(target_value),
            "matches_found": 0,
            "matched_items": [],
            "type_mismatches": []
        }
        sample_data = [123, 45.67, True, "hello", ["a", "b"], {"key": "value"}]
        for idx, item in enumerate(sample_data):
            if self.infer_type(item) == results["target_type"]:
                results["matches_found"] += 1
                results["matched_items"].append({
                    "index": idx,
                    "type": self.infer_type(item),
                    "value": str(item)[:50] + ("..." if len(str(item)) > 50 else "")
                })
            elif isinstance(target_value, (int, float)):
                results["type_mismatches"].append({
                    "index": idx,
                    "item_type": self.infer_type(item),
                    "target_type": results["target_type"]
                })
        return results
def run_main():
    checker = ItemChecker()
    test_cases = [123, 45.67, True, "hello", ["a", "b"], {"key": "value"}]
    target_values = [999, 88.88, False, "world"]
    for i, target in enumerate(target_values):
        self_logger = Logger()
        checker_instance = ItemChecker()
        results = checker_instance.check_item(target)
        self_logger.log("INFO", f"Testing target: {target} (Type: {results['target_type']})")
        for match in results["matched_items"]:
            self_logger.log("INFO", f"Match found at index {match['index']} of type '{match['type']}'")
        if results.get("matches_found", 0) == 0 and not isinstance(target, (int, float)):
            pass 
    summary = checker_instance.logger.get_log_summary()
    final_report = {
        "test_cases_run": len(test_values := target_values),
        "log_stats": summary,
        "final_target_info": checker_instance.check_item(target_values[0]) if test_values else {}
    }
    print("\n--- Final Report ---")
    json_output = json.dumps(final_report, indent=2)
    self_logger.log("INFO", f"Report generated: {json_output}")
if __name__ == '__main__':
    run_main()

import json
import logging
from typing import Any, Dict, List, Union
logging.basicConfig(
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - [%(funcName)s] - Message: %(message)s',
    handlers=[
        logging.FileHandler('item_checker.log'),
        logging.StreamHandler()
    ]
)
logger = logging.getLogger(__name__)
def infer_type(value: Any) -> str:
    if isinstance(value, bool):
        return 'bool'
    elif isinstance(value, int):
        return 'int'
    elif isinstance(value, float):
        return 'float'
    elif isinstance(value, str):
        return 'str'
    elif isinstance(value, list):
        return 'list'
    elif isinstance(value, dict):
        return 'dict'
    else:
        return type(value).__name__
def check_item_presence(
    target_value: Any, 
    data_sources: List[Dict[str, Any]], 
    case_sensitive: bool = True
) -> Dict[str, Union[int, str]]:
    results = {}
    for source in data_sources:
        source_name = source.get('source_name', 'unknown')
        try_data = source.get('data', [])
        logger.info(f"Checking {target_value} against source '{source_name}'")
        if not isinstance(target_value, str):
            found_count = 0
            if isinstance(target_data := [t for t in try_data], list) and len(try_data) > 0:
                for item in try_data:
                    if (case_sensitive and item == target_value) or\
                       (not case_sensitive and str(item).lower() == str(target_value).lower()):
                        found_count += 1
            results[source_name] = f"Found {found_count} matches"
        else:
            if isinstance(try_data, list):
                exact_matches = [item for item in try_data if str(item) == target_value]
                case_insensitive_matches = [item for item in try_data if str(item).lower() == target_value.lower()]
                results[source_name] = f"Exact: {len(exact_matches)}, Case-Insensitive: {len(case_insensitive_matches)} matches found."
            else:
                logger.warning(f"No list format expected in source '{source_name}' for string check.")
                results[source_name] = "Check failed due to unexpected data structure"
    return results
def main():
    TARGET_VALUE = 42
    DATA_SOURCES = [
        {
            'source_name': 'inventory_db',
            'data': ['item_01', 'item_02', 'product_A']
        },
        {
            'source_name': 'warehouse_log',
            'data': [{'id': 42, 'name': 'Widget'}, {'id': 99}]
        },
        {
            'source_name': 'sales_records',
            'data': [100, 250.5, -10]
        }
    ]
    logger.info("Starting item presence check for value: " + str(TARGET_VALUE))
    results = check_item_presence(42, DATA_SOURCES, case_sensitive=True)
    print("\n--- Final Report ---")
    logger.info("Final Report Generated")
    for source_name, message in results.items():
        status = "FOUND" if "Found" in str(message) else "NOT FOUND/ERROR"
        logger.critical(f"[{status}] Source: {source_name} - Details: {message}")
if __name__ == '__main__':
    main()

import json
import logging
from typing import Any, Dict, List, Union
logging.basicConfig(
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - [%(funcName)s] - %(message)s'
)
logger = logging.getLogger(__name__)
class ItemPresenceChecker:
    def __init__(self):
        self.check_history: List[Dict[str, Any]] = []
    def check_presence(self, target_value: Any, source_data: Union[List[Any], Dict[str, Any]]) -> bool:
        logger.info(f"Checking presence of {target_value} in source data")
        try:
            if isinstance(source_data, list):
                found = False
                for item in source_data:
                    if self._deep_equal(target_value, item):
                        found = True
                        logger.debug(f"Found match at index {source_data.index(item)}")
                        break
            elif isinstance(source_data, dict):
                found_in_keys = target_value in source_data.keys()
                found_in_values = any(self._deep_equal(target_value, v) for v in source_data.values())
                if found_in_keys:
                    logger.debug(f"Found match as a key")
                    return True
                elif found_in_values:
                    logger.debug("Found match as a value")
                    return True
            else:
                logger.warning(f"Unsupported data type for source_data: {type(source_data)}")
        except Exception as e:
            logger.error(f"Error during presence check: {str(e)}", exc_info=True)
            raise
        return False
    def _deep_equal(self, a: Any, b: Any) -> bool:
        if type(a) != type(b):
            return False
        try:
            json_str_a = json.dumps(a, sort_keys=True)
            json_str_b = json.dumps(b, sort_keys=True)
            return json_str_a == json_str_b
        except (TypeError, ValueError):
            try:
                import collections.abc
                if isinstance(a, dict) and isinstance(b, dict):
                    return a.keys() == b.keys() and all(self._deep_equal(x, y) 
                                                       for x in a.values() for y in b.values())
                elif isinstance(a, (list, tuple)) and isinstance(b, (list, tuple)):
                    if len(a) != len(b):
                        return False
                    return all(self._deep_equal(i, j) for i, j in zip(a, b))
            except Exception:
                pass
        return a == b and isinstance(type(a), type)
    def run_comprehensive_check(self):
        logger.info("Starting comprehensive item presence check")
        samples = {
            "mixed_list": [1, 2.5, "apple", {"key": "value"}, None],
            "target_int": 42,
            "target_float": 3.14,
            "target_string": "banana",
            "target_nested_dict": {"nested_key": "found_value"}
        }
        result = self.check_presence(samples["mixed_list"], samples["target_int"])
        logger.info(f"Result for int check: {result}")
        result_float = self.check_presence(samples["mixed_list"], samples["target_float"])
        logger.info(f"Result for float check: {result_float}")
        result_str = self.check_presence(samples["mixed_list"], samples["target_string"])
        logger.info(f"Result for string check: {result_str}")
        target_nested = {"nested_key": "found_value"}
        sample_dict_in_list = [1, 2.5, "apple", {"key": "value"}, None]
        logger.info("Running specific check for complex object")
        found_complex = self.check_presence(sample_dict_in_list, target_nested)
        logger.info(f"Result for nested dict check: {found_complex}")
        logger.info("Comprehensive checks completed successfully")
if __name__ == '__main__':
    checker = ItemPresenceChecker()
    try:
        checker.run_comprehensive_check()
    except Exception as e:
        logger.critical(f"System failure during execution: {e}", exc_info=True)

