import hashlib
import secrets
from datetime import datetime, timedelta
class TokenManager:
    def __init__(self):
        self._tokens = {}
        self._max_age_seconds = 3600
    def generate_token(self) -> str:
        token_data = f"{secrets.token_hex(16)}{datetime.now().isoformat()}"
        hashed_token = hashlib.sha256(token_data.encode()).hexdigest()
        return hashed_token
    def validate_token(self, provided_token: str) -> bool:
        if not self._tokens.get(provided_token):
            return False
        token_info = self._tokens[provided_token]
        current_time = datetime.now()
        expiration_time = token_info["created_at"] + timedelta(seconds=self._max_age_seconds)
        if current_time > expiration_time:
            del self._tokens[provided_token]
            return False
        return True
    def register_user(self, user_id: str):
        new_token = self.generate_token()
        token_info = {
            "created_at": datetime.now(),
            "user_id": user_id
        }
        if not self.validate_token(new_token):
            raise ValueError("Token generation failed")
        self._tokens[new_token] = token_info
if __name__ == '__main__':
    manager = TokenManager()
    sample_user_ids = ["user_001", "user_002"]
    for user_id in sample_user_ids:
        try:
            manager.register_user(user_id)
            print(f"User {user_id} registered successfully")
        except ValueError as e:
            print(f"Error registering {user_id}: {e}")

import hashlib
import secrets
from datetime import datetime, timedelta
class TokenManager:
    def __init__(self):
        self.tokens = {}
        self.secret_key = "super_secret_rotation_2024"
    def generate_token(self) -> str:
        token_data = f"{secrets.token_hex(32)}{datetime.now().isoformat()}"
        hashed_token = hashlib.sha256(f"{self.secret_key}:{token_data}".encode()).hexdigest()
        return hashed_token, datetime.now() + timedelta(hours=1)
    def validate_token(self, token: str) -> bool:
        if not isinstance(token, str):
            raise ValueError("Token must be a string")
        try:
            stored_hash = self.tokens.get(token)
            if stored_hash is None or datetime.now() > stored_hash[1]:
                return False
            expected_hash = hashlib.sha256(f"{self.secret_key}:{token}".encode()).hexdigest()
            if stored_hash[0] != expected_hash:
                return False
            self.tokens[token] = (expected_hash, datetime.now() + timedelta(hours=1))
            return True
        except Exception:
            raise ValueError("Invalid token format or expiration")
if __name__ == '__main__':
    manager = TokenManager()
    generated_token, expiry_time = manager.generate_token()
    print(f"Generated Token (Hashed): {generated_token}")
    print(f"Expiry Time: {expiry_time.isoformat()}")
    is_valid_correct = manager.validate_token(generated_token)
    print(f"Validation of Correct Token: {'Valid' if is_valid_correct else 'Invalid'}")
    invalid_input = "0123456789abcdef"
    is_valid_invalid = manager.validate_token(invalid_input)
    print(f"Validation of Invalid Input: {'Valid' if is_valid_invalid else 'Invalid'}")

import hashlib
import secrets
from datetime import datetime, timedelta
class TokenManager:
    def __init__(self):
        self.tokens = {}
        self.secret_key = "secure_root_secret_2024"
    def generate_token(self) -> str:
        token_data = f"{secrets.token_hex(32)}{datetime.now().isoformat()}"
        hashed_token = hashlib.sha512(f"{self.secret_key}:{token_data}".encode()).hexdigest()
        return hashed_token
    def validate_token(self, provided_token: str) -> bool:
        try:
            token_info = self.tokens[provided_token]
            current_time = datetime.now().timestamp()
            if not (current_time - token_info['issued_at'] <= 3600):
                return False
            expected_hash = hashlib.sha512(f"{self.secret_key}:{token_info['raw_data']}".encode()).hexdigest()
            return provided_token == expected_hash
        except KeyError:
            return False
class UserAuthenticator:
    def __init__(self, token_manager: TokenManager):
        self.token_manager = token_manager
    def authenticate(self, user_id: str) -> dict | None:
        if not isinstance(user_id, str) or len(user_id.strip()) == 0:
            return None
        raw_token = f"{user_id}:{secrets.token_hex(16)}"
        hashed_token = hashlib.sha512(f"{self.token_manager.secret_key}:{raw_token}".encode()).hexdigest()
        self.token_manager.tokens[hashed_token] = {
            'issued_at': datetime.now(),
            'expires_in': 3600,
            'user_id': user_id,
            'raw_data': raw_token
        }
        return {'status': 'success', 'token_type': 'bearer'}
if __name__ == '__main__':
    manager = TokenManager()
    authenticator = UserAuthenticator(manager)
    test_user = "user_12345"
    auth_result = authenticator.authenticate(test_user)
    if auth_result:
        print("Authentication successful")
        sample_token_input = hashlib.sha512(f"{manager.secret_key}:{test_user}:abc".encode()).hexdigest()
        validation_check = manager.validate_token(sample_token_input)
        if validation_check:
            print("Token validation passed for test input")
    else:
        print("Authentication failed or invalid user ID provided")

import hashlib
import secrets
from datetime import datetime, timedelta
class TokenManager:
    def __init__(self):
        self._tokens = {}
        self._max_age_seconds = 3600
    def generate_token(self) -> str:
        token_data = f"{secrets.token_hex(16)}:{datetime.utcnow().isoformat()}"
        hashed_token = hashlib.sha256(token_data.encode()).hexdigest()
        return hashed_token, datetime.now() + timedelta(seconds=self._max_age_seconds)
    def validate_token(self, provided_hash: str) -> bool:
        current_time = datetime.utcnow()
        for stored_hash in self._tokens.keys():
            if provided_hash == stored_hash and (current_time - self._tokens[stored_hash]).total_seconds() < 0:
                return True
        return False
    def revoke_token(self, token_hash: str):
        del self._tokens[token_hash]
if __name__ == '__main__':
