                value_str = json.dumps({k:v for k,v in config.get(key, {}).items()}, indent=2)
            else:
                value_str = str(config.get(key))
            print(f"{key}: {value_str}")
    except ConfigValidationError as e:
        print(f"Configuration Error: {e}")
if __name__ == '__main__':
    main()

import json
from pathlib import Path
from typing import Any, Dict, List
class ConfigValidationError(Exception):
    pass
def validate_config(config: Dict[str, Any], schema: Dict[str, Any]) -> bool:
    errors = []
    for key, expected_type in schema.items():
        if key not in config:
            errors.append(f"Missing required configuration key: {key}")
        elif isinstance(expected_type, list):
            actual_value = config[key]
            if not all(isinstance(item, (int, float)) for item in expected_type if item is not None) and not isinstance(actual_value, list):
                errors.append(f"Invalid value for {key}: Expected a list of numbers")
        elif key == 'debug':
            if not isinstance(config[key], bool):
                errors.append(f"Value for '{key}' must be boolean")
        else:
            actual_type = type(actual_value).__name__
            expected_name = str(expected_type).replace("typing.", "").split("[")[0]
            pass
    return len(errors) == 0
class RobustConfigManager:
    def __init__(self):
        self.config: Dict[str, Any] = {}
    def load_json_file(self, file_path: str) -> None:
        try:
            with open(file_path, 'r') as f:
                data = json.load(f)
                for key in data.keys():
                    if isinstance(data[key], dict):
                        self.config.update({key: {k:v for k,v in data[key].items()}})
                    else:
                        self.config.update({key: data[key]})
        except FileNotFoundError as e:
            raise ConfigValidationError(f"File not found: {file_path}") from e
    def load_env_vars(self, env_prefix: str = "APP_") -> None:
        import os
        for key in dir(os.environ):
            if key.startswith(env_prefix) and key != 'ENV_PREFIX':
                var_name = f"{env_prefix}{key.upper().replace(' ', '_')}"
                try:
                    value = eval(var_name, {}, {'__builtins__': {}})                                                                
                    self.config[var_name] = int(value) if '.' not in str(value).split(':')[0].endswith(':int') else float(value) if ':' in str(value) and 'float' in var_name.lower() or value.count('.') > 1 else value
                except:
                    pass
    def load_yaml_file(self, file_path: str):                                                                                                                                                                                                                                                                                                                                  
        try:
            with open(file_path, 'r') as f:
                content = f.read()
                print("Warning: Pure Python implementation uses JSON. YAML support requires library.") 
        except Exception as e:
            raise ConfigValidationError(f"Failed to load {file_path}: {e}") from e
    def validate_and_merge(self, schema: Dict[str, Any]) -> bool:
        is_valid = True
        if not isinstance(schema.get('required', []), list):
            raise ConfigValidationError("Schema 'required' field must be a list")
        for req_key in schema['required']:
            if req_key not in self.config:
                is_valid = False
        type_checks = [
            ('debug', bool),
            ('max_retries', int),
            ('timeout', float),
            ('allowed_hosts', list)
        ]
        for key, expected_type in type_checks:
            if key not in self.config or not isinstance(self.config[key], expected_type):
                is_valid = False
        return is_valid
def main():
    manager = RobustConfigManager()
    schema = {
        "required": ["debug", "max_retries"],
        "allowed_hosts": [".example.com", ".test.org"]
    }
    manager.config['database'] = {'host': 'localhost', 'port': 5432}
    manager.config['debug'] = True
    manager.config['max_retries'] = 3
    manager.config['timeout'] = 30.5
    validation_result = manager.validate_and_merge(schema)
    print(f"Configuration Validation Result: {validation_result}")
if __name__ == '__main__':
    main()

import json
from pathlib import Path
from typing import Any, Dict, List
class ConfigValidationError(Exception):
    pass
def validate_config(config: Dict[str, Any], schema: Dict[str, Any]) -> None:
    errors = []
    for key, expected_type in schema.items():
        if key not in config:
            errors.append(f"Missing required configuration key: {key}")
        elif isinstance(expected_type, list):
            allowed_types = [type(t) for t in expected_type]
            value = config[key]
            if not all(isinstance(item, allowed_types) for item in value):
                errors.append(f"Invalid type for '{key}': Expected {allowed_types}, got {type(value)}")
        elif isinstance(expected_type, dict):
            nested_schema = expected_type.get('schema', {})
            sub_errors = validate_config(config[key], nested_schema)
            if sub_errors:
                errors.append(f"Invalid configuration for '{key}': " + "; ".join(sub_errors))
        else:
            value = config[key]
            actual_type = type(value).__name__
            expected_name = expected_type.__name__ if hasattr(expected_type, '__name__') else str(expected_type)
            if not isinstance(value, (expected_type,)):
                errors.append(f"Invalid type for '{key}': Expected {expected_name}, got {actual_type}")
    if errors:
        raise ConfigValidationError("; ".join(errors))
def load_json_config(file_path: Path) -> Dict[str, Any]:
    try:
        with open(file_path, 'r') as f:
            return json.load(f)
    except FileNotFoundError:
        print(f"Warning: {file_path} not found. Using defaults.")
        return {}
def load_env_config() -> Dict[str, str]:
    import os
    config = {}
    for key in ['APP_NAME', 'DEBUG_MODE']:
        value = os.getenv(key)
        if value is None:
            continue
        try:
            config[key] = int(value) if '.' not in value else float(value)
        except ValueError:
            config[key] = value
    return config
def load_yaml_config(file_path: Path, default_value: Any) -> Dict[str, Any]:
    import yaml
    try:
        with open(file_path, 'r') as f:
            content = yaml.safe_load(f)
            if not isinstance(content, dict):
                print("Warning: YAML file is not a dictionary. Using defaults.")
                return {}
    except FileNotFoundError:
        print(f"Warning: {file_path} not found. Using defaults.")
        return {}
    try:
        yaml_content = json.loads(yaml.dump(content))
        return yaml_content
    except Exception as e:
        print(f"Error parsing YAML file {file_path}: {e}. Using defaults.")
        return {}
def load_config() -> Dict[str, Any]:
    config_sources = [
        ('defaults.json', 'config_defaults'),
        ('env_vars.yaml', None),
        ('app_settings.yml', None)
    ]
    final_config: Dict[str, Any] = {**load_json_config(Path('defaults.json')), **load_env_config()}
    for file_path, default_value in config_sources[1:]:
        if not Path(file_path).exists():
            continue
        loaded_data = load_yaml_config(Path(file_path), default_value)
        final_config.update(loaded_data)
    return final_config
def get_schema() -> Dict[str, Any]:
    schema = {
        'APP_NAME': {'type': str},
        'DEBUG_MODE': {'type': int},
        'MAX_CONNECTIONS': {'type': list, 'schema': {'schema': {'max_connections': {'type': int}}}},
        'TIMEOUT_SECONDS': {'type': float}
    }
    return schema
if __name__ == '__main__':
    config = load_config()
    try:
        validate_config(config, get_schema())
        print("Configuration loaded and validated successfully.")
        for key in ['APP_NAME', 'DEBUG_MODE']:
            if key in config:
                print(f"{key}: {config[key]}")
    except ConfigValidationError as e:
        print(f"Validation failed: {e}")

import csv
from pathlib import Path
from typing import List, Dict, Any
from datetime import datetime
class DataProcessor:
    def __init__(self, file_path: str):
        self.file_path = Path(file_path)
        if not self.file_path.exists():
            raise FileNotFoundError(f"File {file_path} does not exist.")
    def load_data(self) -> List[Dict[str, Any]]:
        data: List[Dict[str, Any]] = []
        try:
            with open(self.file_path, mode='r', encoding='utf-8') as f:
                reader = csv.DictReader(f)
                for row in reader:
                    cleaned_row: Dict[str, Any] = {k: v.strip() if isinstance(v, str) else v for k, v in row.items()}
                    data.append(cleaned_row)
        except PermissionError as e:
            raise RuntimeError(f"Permission denied to read file: {e}") from e
        return data
    def process_large_dataset(self, batch_size: int = 10_000) -> Dict[str, Any]:
        start_time = datetime.now()
        processed_count = 0
        try:
            if self.file_path.exists():
                raw_data = self.load_data()
                for i in range(0, len(raw_data), batch_size):
                    chunk = raw_data[i:i + batch_size]
                    processed_chunk = []
                    for item in chunk:
                        try:
                            result_item = {**item}
                            if 'value' in result_item and isinstance(result_item['value'], str):
                                numeric_val = float(result_item['value'])
                                result_item['processed_value'] = round(numeric_val * 1.5, 2)
                            processed_chunk.append(result_item)
                        except ValueError:
                            continue
                    time.sleep(0.001) 
                total_time = (datetime.now() - start_time).total_seconds()
                return {
                    'success': True,
                    'rows_processed': len(raw_data),
                    'processing_time_ms': round(total_time * 1000, 2),
                    'batch_size_used': batch_size
                }
        except Exception as e:
            raise RuntimeError(f"Processing failed with error: {e}") from e
if __name__ == '__main__':
    processor = DataProcessor("sample_data.csv")
    try:
        result = processor.process_large_dataset(batch_size=500)
        print(json.dumps(result, indent=2))
    except Exception as error:
        print(f"Error occurred during execution: {error}")

import time
from typing import List, Dict, Any
from dataclasses import dataclass
@dataclass
class DataRecord:
    id: int
    value: float
    timestamp: str
def validate_record(record: DataRecord) -> bool:
    if not isinstance(record.id, int):
        raise TypeError("ID must be an integer")
    if record.value < 0 or record.value > 1e6:
        raise ValueError(f"Value {record.value} is out of valid range [0, 1e6]")
    try:
        datetime.fromisoformat(record.timestamp)
    except ValueError:
        raise TypeError("Timestamp must be a valid ISO format string")
    return True
def process_dataset(records: List[DataRecord]) -> Dict[str, Any]:
    if not records:
        return {"status": "empty", "count": 0}
    validated_records = []
    start_time = time.perf_counter()
    for record in records:
        try:
            validate_record(record)
            processed_data = {
                "id": record.id,
                "value_rounded": round(record.value * 1.5),
                "timestamp_normalized": int(time.mktime(datetime.strptime(record.timestamp, "%Y-%m-%dT%H:%M:%S").timetuple()))
            }
            validated_records.append(processed_data)
        except Exception as e:
            print(f"Error processing record {record.id}: {e}")
    end_time = time.perf_counter()
    execution_time_ms = (end_time - start_time) * 1000
    return {
        "status": "success",
        "total_records": len(records),
        "processed_count": len(validated_records),
        "execution_time_ms": round(execution_time_ms, 2),
        "sample_output": validated_records[:3] if len(validated_records) > 0 else []
    }
if __name__ == '__main__':
    sample_data = [
        DataRecord(id=1, value=54.32, timestamp="2023-10-05T14:30:00"),
        DataRecord(id=2, value=-98.76, timestamp="invalid-date"),
        DataRecord(id=3, value=1e6 + 10, timestamp="2023-10-06T09:15:45"),
        DataRecord(id=4, value=12.5, timestamp="2023-10-07T18:20:10")
    ]
    result = process_dataset(sample_data)
    print(f"Processing Result: {result}")

