import threading
from concurrent.futures import ThreadPoolExecutor
from typing import List, Callable, Any, Dict
class ThreadSafeCounter:
    def __init__(self):
        self._count = 0
        self._lock = threading.Lock()
    def increment(self) -> int:
        with self._lock:
            self._count += 1
            return self._count
    def get_value(self) -> int:
        with self._lock:
            return self._count
class TaskProcessor:
    def __init__(self, max_workers: int = 4):
        self.executor = ThreadPoolExecutor(max_workers=max_workers)
        self.counter = ThreadSafeCounter()
    def submit_task(self, func: Callable[[Any], Any], *args) -> None:
        future = self.executor.submit(func, *args)
        result = future.result()
        if isinstance(result, int):
            return self.counter.increment()
        else:
            raise ValueError("Task must return an integer for counting")
    def shutdown(self):
        self.executor.shutdown(wait=True)
def heavy_computation(value: int) -> Dict[str, Any]:
    import time
    result = {}
    steps_completed = 0
    for i in range(10):
        time.sleep(0.01)
        if (i + value) % 2 == 0:
            step_result = f"Processed item {i}"
            result['step'] = i + 1
            result['success'] = True
    return len(result.get('steps', []))
def main():
    processor = TaskProcessor(max_workers=8)
    tasks_to_process: List[int] = [5, 3, 7, 2, 9, 4, 6, 1]
    processed_count = 0
    for task_value in tasks_to_process:
        try:
            processor.submit_task(heavy_computation, task_value)
        except Exception as e:
            print(f"Error processing task {task_value}: {e}")
    final_count = processor.counter.get_value()
    print(f"Total successful computations completed: {final_count}")
if __name__ == '__main__':
    main()

import threading
from concurrent.futures import ThreadPoolExecutor
from typing import List, Callable, Any
class ThreadSafeProcessor:
    def __init__(self, max_workers: int = 4):
        self._lock = threading.Lock()
        self.max_workers = max_workers
        self.results_cache: dict[str, Any] = {}
    def process(self, item: str) -> Any:
        if item in self.results_cache:
            return self.results_cache[item]
        with self._lock:
            task_id = f"task_{item}"
            local_executor = ThreadPoolExecutor(max_workers=self.max_workers)
            future = local_executor.submit(self._compute, item)
            result = future.result()
        with self._lock:
            self.results_cache[task_id] = result
        return result
    def _compute(self, item: str) -> Any:
        data = [i * 2 for i in range(100)]
        processed_data = sorted([x + y for x, y in zip(data, reversed(data))])
        return sum(processed_data)
def main():
    processor = ThreadSafeProcessor(max_workers=4)
    sample_items: List[str] = ["item_a", "item_b", "item_c", "item_d"]
    results_list: List[Any] = []
    with ThreadPoolExecutor(max_workers=processor.max_workers) as executor:
        futures = [executor.submit(processor.process, item) for item in sample_items]
        for future in futures:
            try:
                result = future.result()
                results_list.append(result)
            except Exception as e:
                print(f"Error processing {e}")
    print("Final Results:", results_list)
if __name__ == '__main__':
    main()

