import json
def build_item_list(data):
    items = []
    for key in sorted(data.keys()):
        value = data[key]
        if isinstance(value, dict):
            nested_items = {k: v for k, v in value.items() if not (isinstance(v, str) and 'hidden' in v.lower())}
            items.append({key: nested_items})
    return {"items": items}
