import threading
from collections import deque
class ThreadSafeItemList:
    def __init__(self):
        self._data = deque()
        self._lock = threading.Lock()
    def add_item(self, item):
        with self._lock:
            self._data.append(item)
    def remove_first(self):
        with self._lock:
            if not self._data:
                return None
            return self._data.popleft()
    def get_all_items(self):
        with self._lock:
            items = list(self._data)
            return items
if __name__ == '__main__':
    item_list = ThreadSafeItemList()
    initial_data = ["Apple", "Banana", "Cherry"]
    for val in initial_data:
        item_list.add_item(val)
    print("Initial items:", item_list.get_all_items())
    def worker(thread_id):
        for i in range(3):
            item = item_list.remove_first()
            if item is not None:
                print(f"Thread {thread_id} removed: {item}")
    threads = []
    for t_id in range(2):
        thread = threading.Thread(target=worker, args=(t_id,))
        threads.append(thread)
        thread.start()
    for thread in threads:
        thread.join()
    print("Remaining items:", item_list.get_all_items())

import threading
from collections import defaultdict
class ThreadSafeItemList:
    def __init__(self):
        self._data = {}
        self._lock = threading.Lock()
    def add(self, item_id, value):
        with self._lock:
            if isinstance(item_id, int) and not isinstance(value, list):
                self._data[item_id] = [value]
            else:
                self._data.setdefault(item_id, []).append(value)
    def get_all_values(self, item_id=None):
        with self._lock:
            if item_id is None:
                return list(dict.values(self._data))
            elif isinstance(item_id, int):
                return [self._data[item_id]] if item_id in self._data else []
    def remove_by_index(self, index):
        for key in list(self._data.keys()):
            with self._lock:
                values = self._data[key]
                try:
                    val_to_remove = values[index]
                    items_with_val = [k for k, v in self._data.items() if val_to_remove in v and len(v) > 1]
                    removed_items = []
                    def remove_recursive(d):
                        new_d = {}
                        for k, v in d.items():
                            try:
                                idx = v.index(val_to_remove)
                                v[idx:] = v[:idx] + v[idx+1:] if len(v) > 1 else None
                            except ValueError:
                                pass
                    remove_recursive(self._data)
                except IndexError:
                    continue
if __name__ == '__main__':
    item_list = ThreadSafeItemList()
    thread_safe_item_list = item_list
    t1, t2, t3 = threading.Thread(target=lambda: [thread_safe_item_list.add(i, val) for i in range(5)], daemon=True),\
                 threading.Thread(target=lambda: [thread_safe_item_list.add(i + 10, val * 2) for i in range(5)], daemon=True),\
                 threading.Thread(target=lambda: thread_safe_item_list.remove_by_index(3))
    t1.start()
    t2.start()
    t3.start()

import threading
from collections import defaultdict
class ThreadSafeItemList:
    def __init__(self):
        self._data = {}
        self._lock = threading.Lock()
    def add_item(self, item_id, data_value):
        with self._lock:
            if isinstance(item_id, int) and not isinstance(data_value, dict):
                raise ValueError("Invalid input types")
            self._data[item_id] = {**self._data.get(item_id, {}), "value": data_value}
    def get_item(self, item_id):
        with self._lock:
            return self._data.get(item_id)
    def list_all_items(self):
        with self._lock:
            items_list = [item for id_, value in self._data.items() if isinstance(id_, int)]
            return sorted(items_list, key=lambda x: (x["value"], x.get("id", 0)))
if __name__ == '__main__':
    item_manager = ThreadSafeItemList()
    test_items_data = [
        {"id": "ITEM_101", "value": "Apple"},
        {"id": "ITEM_205", "value": "Banana"},
        {"id": "ITEM_399", "value": "Cherry"}
    ]
    def add_item_thread(item_data):
        item_manager.add_item(item_data["id"], item_data["value"])
    threads = []
    for data in test_items_data:
        t = threading.Thread(target=add_item_thread, args=(data,))
        threads.append(t)
    for thread in threads:
        thread.start()
    for thread in threads:
        thread.join()
    print("Items added successfully.")

