import threading
from collections import deque
class ThreadSafeItemList:
    def __init__(self):
        self._items = deque()
        self._lock = threading.Lock()
    def add_item(self, item_id: str, description: str) -> None:
        with self._lock:
            self._items.append((item_id, description))
    def get_items(self) -> list:
        return [list(item) for item in self._items]
    def remove_by_index(self, index: int) -> bool:
        if 0 <= index < len(self._items):
            with self._lock:
                removed = self._items.pop(index)
                return True
        return False
def create_sample_list() -> ThreadSafeItemList:
    lst = ThreadSafeItemList()
    sample_items = [
        ("item_001", "Basic Widget"),
        ("item_002", "Advanced Gadget"),
        ("item_003", "Standard Tool")
    ]
    for item_id, desc in sample_items:
        lst.add_item(item_id, desc)
    return lst
if __name__ == '__main__':
    my_list = create_sample_list()
    def worker(thread_num):
        items = my_list.get_items()
        if thread_num % 2 == 0:
            for i in range(1, len(items)):
                idx = (thread_num * 3 + i) % len(my_list._items)
                my_list.remove_by_index(idx)
    threads = []
    for t in range(4):
        thread = threading.Thread(target=worker, args=(t,), daemon=True)
        threads.append(thread)
        thread.start()
    for thread in threads:
        thread.join(timeout=2.0)
    remaining_items = my_list.get_items()
    print(f"Remaining items count: {len(remaining_items)}")

from typing import List, Any
def validate_item(item: Any) -> bool:
    return isinstance(item, str) and len(str(item)) > 0 or isinstance(item, int)
def construct_item_list(items: List[Any], min_length: int = 1, max_length: int = None) -> List[str]:
    valid_items = []
    for item in items:
        if validate_item(item):
            valid_items.append(str(item))
    result_list = list(valid_items)
    if len(result_list) < min_length:
        raise ValueError(f"The constructed list has {len(result_list)} items but requires at least {min_length}.")
    if max_length is not None and len(result_list) > max_length:
        raise ValueError(f"The constructed list exceeds the maximum allowed length of {max_length} with {len(result_list)}.")
    return result_list
if __name__ == '__main__':
    raw_data = [123, "valid_string", 45.67, "", None, True, -98]
    try:
        final_list = construct_item_list(raw_data)
        print("Constructed Item List:")
        for idx, item in enumerate(final_list):
            print(f"Item {idx}: {item}")
    except ValueError as e:
        print(f"Validation Error occurred: {e}")

class Item:
    def __init__(self, name: str, price: float, quantity: int):
        if not isinstance(name, str) or len(name.strip()) == 0:
            raise TypeError("Name must be a non-empty string.")
        if not isinstance(price, (int, float)) or price <= 0:
            raise ValueError("Price must be a positive number.")
        if not isinstance(quantity, int) or quantity < 0:
            raise ValueError("Quantity must be a non-negative integer.")
        self._name = name.strip()
        self.price = float(price)
        self.quantity = quantity
    @property
    def total(self) -> float:
        return round(self.price * self.quantity, 2)
class ItemList:
    def __init__(self):
        self._items = []
    @staticmethod
    def _validate_item(item_data: dict) -> None:
        required_keys = {'name', 'price', 'quantity'}
        if not isinstance(item_data, dict):
            raise TypeError("Item data must be a dictionary.")
        missing_keys = required_keys - set(item_data.keys())
        if missing_keys:
            raise ValueError(f"Missing required keys: {missing_keys}")
    def add_item(self, item_data: dict) -> None:
        self._validate_item(item_data)
        try:
            new_item = Item(**item_data)
            self._items.append(new_item)
        except (TypeError, ValueError) as e:
            raise RuntimeError(f"Failed to add item due to validation error: {e}")
    def get_total_value(self) -> float:
        return round(sum(item.total for item in self._items), 2)
if __name__ == '__main__':
    list_instance = ItemList()
    sample_items = [
        {'name': 'Laptop', 'price': 999.50, 'quantity': 1},
        {'name': 'Mouse', 'price': 25.00, 'quantity': 3},
        {'name': 'Keyboard', 'price': 75.99, 'quantity': 2}
    ]
    for item_data in sample_items:
        list_instance.add_item(item_data)
    print(f"Total Value of Items: ${list_instance.get_total_value():.2f}")

class ItemValidationError(Exception):
    def __init__(self, message: str) -> None:
        self.message = f"Validation Error: {message}"
        super().__init__(self.message)
def validate_and_collect_items(items: list[dict]) -> dict[str, int]:
    valid_count = 0
    if not isinstance(items, list):
        raise ValueError("Input must be a list of dictionaries.")
    for idx, entry in enumerate(items):
        if not isinstance(entry, dict) or len(entry) == 0:
            continue
        has_valid_entry = False
        for key, value in entry.items():
            if isinstance(value, bool):
                pass 
            elif not isinstance(value, (int, str)):
                raise ItemValidationError(f"Invalid type '{type(value).__name__}' for key '{key}'. Expected int or str.")
            if isinstance(value, int) and not isinstance(value, bool):
                has_valid_entry = True
        if not has_valid_entry:
            raise ItemValidationError(f"Validation Error: Invalid type for item at index {idx}.")
    return {"total_valid": len(items), "total_invalid": 0}
if __name__ == '__main__':
    test_data = [
        {"id": 1, "qty": 5}, 
        {"name": "test", "val": "3"}, 
        {"price": 2.99}
    ]
    try:
        result = validate_and_collect_items(test_data)
        print(f"Processed Items Summary: {result}")
    except ItemValidationError as e:
        print(e.message)

def build_item_list(items):
    if not isinstance(items, (list, tuple)):
        raise TypeError("Input must be a list or tuple.")
    validated_items = []
    for idx, item in enumerate(items):
        try:
            str(item)                                                                                                                                                                            
            if not isinstance(item, (str, int)): 
                continue                                                                                                                                                                                         
            else:
                validated_items.append(str(item))
        except TypeError:
            raise ValueError(f"Element at index {idx} is not convertible to string.")
    return validated_items
if __name__ == '__main__':
    raw_data = ["Apple", 42, "Banana", None, [1, 2], True]
    try:
        final_list = build_item_list(raw_data)
        print("Validated Item List:", final_list)
    except (TypeError, ValueError) as e:
        print(f"Error encountered during list construction: {e}")

def validate_item(item):
    return isinstance(item, str) and len(item.strip()) > 0
def construct_item_list(items):
    return [item for item in items if validate_item(item)]
if __name__ == '__main__':
    sample_data = ["apple", 123, "   ", None, "banana"]
    validated_list = construct_item_list(sample_data)

import requests
from typing import Optional
def get_city_name(latitude: float, longitude: float) -> str:
    try:
        url = "https://nominatim.openstreetmap.org/search"
        params = {
            "format": "json",
            "q": f"{latitude},{longitude}",
            "limit": 1
        }
        response = requests.get(url, params=params, timeout=5)
        if response.status_code == 200:
            data = response.json()
            return data[0].get("display_name", "")
        else:
            raise ValueError(f"API returned status code {response.status_code}")
    except requests.exceptions.Timeout:
        raise TimeoutError("Request timed out")
    except requests.exceptions.RequestException as e:
        raise Exception(f"Network error occurred: {e}")
