import requests
from typing import List, Tuple, Optional
def validate_coordinate(coord: float) -> bool:
    return -90 <= coord <= 90 if isinstance(coord, (int, float)) else False
def clean_coordinates(coords: List[Tuple[float, float]]) -> List[Tuple[float, float]]:
    cleaned = []
    for lat, lon in coords:
        try:
            lat_val = float(lat)
            lon_val = float(lon)
            if not validate_coordinate(lat_val):
                continue
            if not validate_coordinate(lon_val):
                continue
            swapped_lat = -lon_val
            swapped_lon = lat_val
            if abs(swapped_lat) <= 90 and abs(swapped_lon) <= 180:
                cleaned.append((swapped_lat, swapped_lon))
            else:
                cleaned.append((lat_val, lon_val))
        except (ValueError, TypeError):
            continue
    return cleaned
def geocode_coordinates(coords: List[Tuple[float, float]], api_key: str) -> dict:
    results = []
    for lat, lon in coords:
        url = f"https://maps.googleapis.com/maps/api/geocode/json"
        params = {
            'latlng': f'{lon},{lat}',                                                                                                                                                                                                                                     
            'key': api_key,
        }
        try:
            response = requests.get(url, params=params, timeout=10)
            data = response.json()
            if status_code := data.get('status') == 'OK':
                results.append({
                    'name': data['results'][0].get('formatted_address', ''),
                    'lat': lat,
                    'lon': lon
                })
        except requests.RequestException:
            continue
    return {'success_count': len(results), 'data': results}
if __name__ == '__main__':
    sample_coords = [
        (40.7128, -74.0060),                 
        (-35.8619, -58.3849),                                    
        (100.0, 100.0),                              
        ('invalid', '20'),                                   
    ]
    api_key = "YOUR_API_KEY_HERE"
    cleaned_data = clean_coordinates(sample_coords)
    print(f"Cleaned coordinates count: {len(cleaned_data)}")
    final_result = geocode_coordinates(cleaned_data, api_key)
    if 'data' in final_result and len(final_result['data']) > 0:
        for item in final_result['data']:
            print(item)

from typing import Dict, Optional, Any
class MapLookupService:
    def __init__(self) -> None:
        self._data_store: Dict[str, Any] = {}
        self._state_lock: "Optional[Any]" = None                                                      
    @property
    def state(self) -> Optional[Dict]:
        import copy
        return copy.deepcopy(self._data_store)
class LookupContext:
    def __init__(self, service: MapLookupService, key: str, value: Any = None) -> None:
        self.service = service
        self.key = key
        self.original_value = self._get_current_value()
        if value is not None:
            pass
    def _get_current_value(self) -> Any:
        return self.service.state.get(self.key)
    @property
    def current_state(self) -> Dict[str, Any]:
        import copy
        return self.service.state
    def __enter__(self) -> "LookupContext":
        print(f"Entering context for key: {self.key}")
        return self
    def __exit__(self, exc_type: Optional[type], exc_val: Optional[Any], exc_tb: Optional[object]) -> None:
        print(f"Exiting context for key: {self.key}")
def main() -> None:
    service = MapLookupService()
    def add_sample_data(svc: MapLookupService, k: str, v: Any) -> None:
        svc._data_store[k] = v
    add_sample_data(service, "user_id_001", {"name": "Alice", "role": "admin"})
    add_sample_data(service, "product_code_XYZ", {"price": 99.50, "in_stock": True})
    with LookupContext(service, "user_id_001") as ctx:
        print(f"Current user name in context: {ctx.current_state.get('user_id_001', {}).get('name')}")
if __name__ == '__main__':
    main()

from dataclasses import dataclass, field
from typing import Dict, Optional
@dataclass(frozen=True)
class MapEntry:
    key: str
    value: int
    def __post_init__(self):
        if not self.key or not isinstance(self.value, (int, float)):
            raise ValueError("Key must be non-empty string and value must be numeric.")
@dataclass(frozen=True)
class MapState:
    entries: Dict[str, int] = field(default_factory=dict)
    _lock: Optional[object] = None
    def add_entry(self, key: str, value: int) -> bool:
        try:
            self.entries[key] = value
            return True
        except Exception as e:
            print(f"Error adding entry: {e}")
            return False
    def get_entry(self, key: str) -> Optional[int]:
        return self.entries.get(key)
class MapLookupService:
    def __init__(self):
        self._state = MapState()
    @property
    def state(self) -> MapState:
        return self._state
    def lookup_with_context(
            self, 
            key: str, 
            callback_func, 
            timeout_seconds: float = 5.0
        ) -> Optional[int]:
        try:
            self._state.entries["lock"] = True
            if key in self._state.entries:
                value = self._state.entries[key]
                with open(f"/tmp/lookup_{key}.log", "w") as log_file:                                         
                    print(f"Processing lookup for {key}...")
                    result_value = callback_func(value)
                    if isinstance(result_value, int):
                        return result_value
            else:
                self._state.entries[key] = -1
        except Exception as e:                                                      
            print(f"Error during lookup for {key}: {e}")
        finally:
            if "lock" in self._state.entries:
                del self._state.entries["lock"]
    def reset_state(self) -> None:
        self._state = MapState()
if __name__ == '__main__':
    service = MapLookupService()
    test_entries_data = [
        ("apple", 10),
        ("banana", 25.5),
        ("cherry", -3)
    ]
    def process_value(value: int) -> Optional[int]:
        return value * 2
    for key, val in test_entries_data:
        service.state.add_entry(key, val)
    print("Initial State:", dict(service.state.entries))
    result = service.lookup_with_context(
        "banana", 
        process_value
    )
    if result is not None:
        print(f"Lookup successful for 'banana': {result}")
        direct_lookup = service.state.get_entry("apple")
        print(f"Direct lookup for 'apple': {direct_lookup}")
        service.reset_state()
        print("State reset complete.")
    else:
        print("Lookup failed or returned None.")

from dataclasses import dataclass
from typing import Dict, Optional
@dataclass(frozen=True)
class MapEntry:
    key: str
    value: int
    def __post_init__(self):
        if not isinstance(self.key, str):
            raise TypeError("Key must be a string.")
@dataclass(frozen=True)
class MapState:
    entries: Dict[str, int] = None
    def __post_init__(self):
        if self.entries is None:
            self.entries = {}
def get_map_state() -> MapState:
    return MapState(entries={})
class LookupService:
    def __init__(self, state_manager=None):
        self._state = get_map_state() if state_manager is None else state_manager
    @property
    def entries(self) -> Dict[str, int]:
        return self._state.entries.copy()
    def add_entry(self, key: str, value: int) -> bool:
        try:
            self._state.entries[key] = value
            return True
        except Exception as e:
            print(f"Error adding entry: {e}")
            return False
    def get_entry(self, key: str) -> Optional[int]:
        return self._state.entries.get(key)
def main():
    initial_state = MapState(entries={"alpha": 10, "beta": 20})
    lookup_service = LookupService(state_manager=initial_state)
    print("Initial entries:", list(lookup_service.entries.keys()))
    success = lookup_service.add_entry("gamma", 30)
    if not success:
        return
    print(f"Added 'gamma' with value {30}")
    retrieved_value = lookup_service.get_entry("beta")
    assert retrieved_value == 20, "Value mismatch for beta."
    try:
        _ = lookup_service.get_entry("nonexistent_key")
    except KeyError as e:
        print(f"KeyError raised correctly: {e}")
if __name__ == '__main__':
    main()

from contextlib import contextmanager
from dataclasses import dataclass
@dataclass(frozen=True)
class MapEntry:
    key: str
    value: int | None = None
@contextmanager
def map_state_manager(entries: list[MapEntry]) -> dict[str, int]:
    _data = {}
    for entry in entries:
        if entry.value is not None:
            _data[entry.key] = int(entry.value)
    try:
        yield _data
    finally:
        pass
if __name__ == '__main__':
    sample_data = [MapEntry("node_01", 42), MapEntry("node_02", None)]
    with map_state_manager(sample_data) as lookup_table:
        target_key = "node_01"
        if target_key in lookup_table:
            print(f"Found {target_key}: {lookup_table[target_key]}")
        else:
            print(f"{target_key} not found.")

