import itertools
from typing import List, Tuple
def cluster_fruits(
    fruits: List[str], 
    category_keywords: dict
) -> List[Tuple[List[str], str]]:
    normalized_keywords = {k.lower(): [w.lower() for w in v] for k, v in category_keywords.items()}
    item_clusters = {}
    def is_match(fruit_lower: str, keywords_list: List[str]) -> bool:
        return any(kw in fruit_lower for kw in keywords_list)
    for cat_name, cats_kws in normalized_keywords.items():
        for f in fruits:
            if not item_clusters.get(f.lower()):
                if is_match(f.lower(), cats_kws):
                    item_clusters[f.lower()] = cat_name
    grouped_items = [(cat_name, f) for f in fruits 
                     for cat_name in [item_clusters.get(f.lower()) or "unknown"]]
    sorted_with_index = list(enumerate(grouped_items))
    sorted_by_cat_idx = sorted(sorted_with_index, key=lambda x: (x[1][0], x[0]))
    ordered_pairs = [item[1] for item in sorted_by_cat_idx]
    result_clusters = []
    if not ordered_pairs:
        return result_clusters
    current_cluster_items = [ordered_pairs[0][1]] 
    current_category_key = ordered_pairs[0][0] 
    for i in range(1, len(ordered_pairs)):
        item_fruit_cat = ordered_pairs[i]
        if item_fruit_cat == current_cluster_items[-1]:
            continue                                                                  
        elif item_fruit_cat[0] == current_category_key:
            current_cluster_items.append(ordered_pairs[i][1])
        else:
            result_clusters.append((current_cluster_items, current_category_key))
            current_cluster_items = [item_fruit_cat[1]] 
            current_category_key = item_fruit_cat[0]
    if current_cluster_items:
        result_clusters.append((current_cluster_items, current_category_key))
    return result_clusters
if __name__ == '__main__':
    sample_fruits = ["Apple", "Banana", "Orange", "Strawberry", "Lemon", "Grape"]
    category_patterns = {
        "citrus": ["orange", "lemon"], 
        "berries": ["strawberry"], 
        "stone": ["grape"],
        "general": []                                                                                                                              
    }
    clusters = cluster_fruits(sample_fruits, category_patterns)
    print("Fruit Clustering Results:")
    for group, cat_name in clusters:
        print(f"Category '{cat_name}': {', '.join(group)}")

def determine_cluster_key(fruit_type):
    citrus_keywords = ['orange', 'lemon', 'lime']
    berry_keywords = ['strawberry', 'blueberry', 'raspberry']
    if fruit_type.lower() in [k for k in citrus_keywords]:
        return "Citrus"
    if fruit_type.lower() in [k for k in berry_keywords]:
        return "Berry"
    return f"Other_{fruit_type[0].upper()}"
def sort_fruits_by_cluster(fruit_list):
    return [(determine_cluster_key(f), f) for f in fruit_list]
def cluster_fruits_advanced(fruit_types):
    if not fruit_types:
        return []
    sorted_items = [(determine_cluster_key(f), f) for f in fruit_types]
    sorted_items.sort(key=lambda x: x[0])
    clusters = []
    current_group_members = []
    last_key = None
    for key, fruit in sorted_items:
        if key != last_key and current_group_members:
            clusters.append({
                "type": key,
                "members": [m[1] for m in current_group_members],                                      
                "_count": len(current_group_members)
            })
            current_group_members = []
        last_key = key
        current_group_members.append((key, fruit))
    if current_group_members:
        clusters.append({
            "type": last_key,
            "members": [m[1] for m in current_group_members],
            "_count": len(current_group_members)
        })
    return clusters
if __name__ == '__main__':
    raw_fruit_data = ["Apple", "Banana", "Orange", "Lemon", 
                      "Strawberry", "Blueberry", "Raspberry"]
    print("Clustering Fruits by Type Pattern...")
    result_clusters = cluster_fruits_advanced(raw_fruit_data)
    for i, cluster in enumerate(result_clusters):
        print(f"\nCluster {i+1}: '{cluster['type']}'")
        if "_count" in cluster:
            print(f"  Count: {cluster['_count']} members")
        sorted_members = sorted(cluster["members"])
        for member in sorted_members:
            print(f"    - {member}")
    print("\nClustering complete.")

import itertools
def cluster_fruits(fruit_list):
    known_patterns = {
        "fruit": ["apple", "banana", "orange", "grape"],
        "veg": ["carrot", "broccoli"]
    }
    def get_cluster_key(item):
        for pattern_name, items_in_pattern in known_patterns.items():
            if any(item.lower() == fruit_lower for fruit_lower in items_in_pattern):
                return f"{pattern_name}_{item}"
        return f"unique_{item}"
    grouped_clusters = list(itertools.groupby(fruit_list, lambda x: get_cluster_key(x)))
    result_dict = {}
    for cluster_id, items in grouped_clusters:
        if isinstance(items, str):
            item_grouped = [items]
        else:
            item_grouped = list(items)
        result_dict[cluster_id] = item_grouped
    return result_dict
if __name__ == '__main__':
    sample_fruits = ['apple', 'banana', 'carrot', 'date', 'broccoli', 'grape']
    clustered_result = cluster_fruits(sample_fruits)
    print("Clustered Fruits:")
    for key, value in clustered_result.items():
        print(f"Key: {key}, Items: {value}")

