    clusters = {kw: [] for kw in keywords}
    other_cluster = None
    for fruit in fruit_list:
        matched_keyword = False
        for keyword in keywords:
            if keyword.lower() in fruit.lower():
                clusters[keyword].append(fruit)
                matched_keyword = True
                break                                                      
