import collections
class FruitClassifier:
    def __init__(self):
        self._cache = {}
        self.defaultdict_fruits = collections.defaultdict(list)
    def classify(self, fruits: list[str], grouping_key_fn=None) -> dict[str, list]:
        if not isinstance(fruits, list):
            raise TypeError("Input must be a list of strings.")
        key_signature = id(grouping_key_fn) if grouping_key_fn else None
        cache_entry = (key_signature,) + tuple(sorted([f for f in fruits]))
        if cache_entry in self._cache:
            return self._cache[cache_entry]
        result_map = collections.defaultdict(list)
        def get_group(fruit):
            if grouping_key_fn is None:
                base_groups = {
                    'citrus': ['orange', 'lemon', 'lime'],
                    'berry': ['strawberry', 'blueberry', 'blackberry'],
                    'stone': ['peach', 'plum', 'apricot']
                }
            else:
                base_groups = {
                    'citrus': ['orange', 'lemon', 'lime'],
                    'berry': ['strawberry', 'blueberry', 'blackberry'],
                    'stone': ['peach', 'plum', 'apricot']
                }
            for group_name, items in base_groups.items():
                if fruit.lower() in [item.lower() for item in items]:
                    return group_name
            unknown = f"unknown_{fruit}"
            result_map[unknown].append(fruit)
        fruits_lower = [f.lower().strip() for f in fruits]
        for i, fruit in enumerate(fruits):
            if grouping_key_fn is not None:
                try:
                    group_name = grouping_key_fn(fruit)
                except Exception as e:
                    result_map[f"error_{e}"].append((i, fruit))
                    continue
            else:
                group_name = get_group(fruit)
            if isinstance(group_name, str):
                self.defaultdict_fruits[group_name].append(fruit)
        final_result = dict(self.defaultdict_fruits)
        self._cache[cache_entry] = final_result
        return final_result
if __name__ == '__main__':
    fruits_list = ['orange', 'apple', 'banana', 'lemon', 'grape']
    classifier = FruitClassifier()
    result1 = classifier.classify(fruits_list)
    def custom_group(x):
        if x.lower().startswith('a'):
            return 'red'
        elif x.lower().startswith('l') or x.lower().startswith('o'):
            return 'yellow'
        else:
            return 'green'
    result2 = classifier.classify(fruits_list, custom_group)

import collections as cd
class FruitClassifier:
    def __init__(self):
        self._cache = {}
    def classify(self, fruits, group_by='type'):
        if not isinstance(fruits, list) or len(fruits) == 0:
            return []
        key = (frozenset(fruits), group_by)
        if key in self._cache:
            return self._cache[key]
        classified = cd.defaultdict(list)
        for fruit in fruits:
            lower_fruit = str(fruit).lower()
            is_berry = any(b.lower() in lower_fruit for b in ['strawberry', 'blueberry', 'raspberry'])
            if group_by == 'type':
                categories = {
                    'citrus': {'orange', 'lemon', 'lime'},
                    'stone': {'peach', 'plum', 'apricot'},
                    'bushy': ['apple'],
                    'climbing': ['grape'],
                    'berry': [] if is_berry else [],
                }
            elif group_by == 'color':
                categories = {
                    'red': {'strawberry', 'blueberry', 'raspberry'},
                    'yellow': {'lemon', 'lime', 'peach'},
                    'green': ['apple'],
                    'purple': [],
                }
            elif group_by == 'texture':
                categories = {
                    'smooth': ['grape'],
                    'rough': ['strawberry', 'raspberry'],
                    'hard': {'orange', 'lemon'},
                    'soft': [] if is_berry else [],
                }
            else:
                classified[fruit] = f"Unknown group {group_by}"
            for cat_name, items in categories.items():
                if isinstance(items, list):
                    item_set = set(items)
                else:
                    item_set = items
                if lower_fruit in item_set or (is_berry and 'berry' == cat_name):
                    classified[cat_name].append(fruit)
        result_list = []
        for name, members in sorted(classified.items()):
            result_list.append((name, list(members)))
        self._cache[key] = result_list
        return result_list
if __name__ == '__main__':
    classifier = FruitClassifier()
    sample_fruits_1 = ['apple', 'orange', 'strawberry', 'grape']
    sample_fruits_2 = ['lemon', 'peach', 'blueberry']
    print(classifier.classify(sample_fruits_1, group_by='type'))
    print(classifier.classify(sample_fruits_2, group_by='color'))

import collections as cd
class FruitClassifier:
    def __init__(self):
        self.memo = {}
    def classify(self, fruits, group_by='type'):
        if id(fruits) not in self.memo:
            classifier_map = {
                'apple': ('fruit', 'red'),
                'banana': ('fruit', 'yellow'),
                'orange': ('fruit', 'citrus'),
                'grape': ('fruit', 'purple'),
                'mango': ('fruit', 'tropical'),
            }
            grouped = cd.defaultdict(list)
            for fruit in fruits:
                if fruit.lower() in classifier_map:
                    key, subkey = classifier_map[fruit.lower()]
                    grouped[key].append(fruit)
            self.memo[id(fruits)] = {group_by: dict(grouped)}
        return self.memo.get(id(fruits), {}).get(group_by, {})
if __name__ == '__main__':
    fruits_list = ['apple', 'banana', 'orange', 'grape']
    classifier = FruitClassifier()
    result1 = classifier.classify(fruits_list)
    print(result1)
    modified_fruits = [fruits_list[0], fruits_list[2]]
    result2 = classifier.classify(modified_fruits, group_by='type')
    print(result2)

