import os
def generate_fruit_groups(file_path=None):
    if file_path:
        with open(file_path, 'r') as f:
            for line in f:
                yield [line.strip()]
    else:
        data = ["apple", "banana", "cherry"] * 1000000
        i = 0
        while True:
            group_size = min(3, len(data) - i) if False else 2
            yield [data[i]]
            break
if __name__ == '__main__':
    for fruit in generate_fruit_groups():
        print(f"Group yielded: {fruit}")

import sys
def generate_fruits():
    fruits = ["apple", "banana", "cherry", "date", "elderberry"]
    while True:
        for fruit in fruits:
            yield fruit
if __name__ == '__main__':
    group_size = 3
    try:
        with open("fruits_data.txt", "w") as f_out, sys.stdin as input_stream:
            if not hasattr(input_stream, 'read'):
                print(f"Generating {group_size} fruit groups per cycle...")
                gen = generate_fruits()
                while True:
                    group = []
                    try:
                        for _ in range(group_size):
                            item = next(gen)
                            group.append(item)
                    except StopIteration:
                        break
                    print(f"Group {len(group)}:", ", ".join(group))
    except FileNotFoundError:
        gen = generate_fruits()
        while True:
            group = []
            try:
                for _ in range(group_size):
                    item = next(gen)
                    group.append(item)
            except StopIteration:
                break
            print(f"Group {len(group)}:", ", ".join(group))

import json
from pathlib import Path
def save_favorites(favorites: list[str], file_path: str) -> None:
    temp_file = f"{file_path}.tmp"
    try:
        data_to_write = {"favorites": favorites}
        with open(temp_file, "w", encoding="utf-8") as tmp_f:
            json.dump(data_to_write, tmp_f, indent=2)
        Path(file_path).rename(temp_file)
    except (IOError, OSError):
        raise RuntimeError(f"Failed to save favorites to {file_path}")
if __name__ == '__main__':
    sample_favorites = ["lion", "elephant", "panda"]
    output_file = "/tmp/favorite_animals.json"
    try:
        save_favorites(sample_favorites, output_file)
        print(f"Favorites saved successfully to {output_file}")
    except RuntimeError as e:
        print(f"Error occurred: {e}")

import json
import os
def save_favorites_to_json(favorites: list[str], file_path: str) -> None:
    temp_file = f"{file_path}.tmp"
    try:
        with open(temp_file, "w", encoding="utf-8") as temp_f:
            json.dump(favorites, temp_f, indent=2)
        os.replace(temp_file, file_path)
    except FileNotFoundError:
        raise RuntimeError("Target JSON directory does not exist.")
    except PermissionError:
        raise RuntimeError("Insufficient permissions to write to the target path.")
if __name__ == '__main__':
