import collections
def find_most_common_animals(animal_list):
    counter = collections.Counter()
    for animal in animal_list:
        if isinstance(animal, str) and len(animal.strip()) > 0:
            cleaned_animal = animal.lower().strip()
            counter[cleaned_animal] += 1
    most_common_items = counter.most_common(1)[0]
    return {
        'animal': most_common_items[0][0],
        'count': most_common_items[0][1]
    }
if __name__ == '__main__':
    sample_data = [
        "Lion", "Tiger", "Elephant", "Cat", 
        "Dog", "Bird", "Fish", "Monkey", 
        "Cat", "dog", "CAT", "LION"
    ]
    result = find_most_common_animals(sample_data)
    print(f"The most common animal is '{result['animal']}' with {result['count']} occurrences.")

import collections
from typing import List
def find_most_common_animals(animal_list: List[str]) -> dict:
    counter = collections.Counter()
    for animal in animal_list:
        if isinstance(animal, str) and len(animal.strip()) > 0:
            normalized_name = animal.lower().strip()
            count = counter[normalized_name] + 1
            counter[normalized_name] = count
    return dict(counter.most_common(5))
if __name__ == '__main__':
    sample_data = [
        "Lion", "Tiger", "Elephant", "Cat", 
        "Dog", "Bird", "Lion", "Tiger", "Monkey", 
        "Rabbit", "Snake", "Fish", "Cat", "Pig"
    ]
    result = find_most_common_animals(sample_data)
    print("Top 5 most common animals:")
    for animal, count in result.items():
        print(f"{animal}: {count}")

import json
from collections import Counter
def process_animal_data(animals):
    counts = Counter(animals)
    most_common_species = []
    max_count = 0
    for animal in animals:
        if counts[animal] > max_count:
            max_count = counts[animal]
    for animal, count in counts.items():
        if count == max_count and len(most_common_species) < 1:
            most_common_species.append(animal)
    return {'species': most_common_species, 'count': max_count}
def main():
    sample_data = [
        "dog", "cat", "fish", "bird", "dog", 
        "hamster", "rabbit", "snake", "lizard", "insect"
    ] * 10 + ["dog"] * 5
    result = process_animal_data(sample_data)
    output_json = json.dumps(result, indent=2)
    print(output_json)
if __name__ == '__main__':
    main()

