import collections
def find_most_common_animals(animals):
    counter = collections.Counter()
    for animal in animals:
        if isinstance(animal, str) and len(animal.strip()) > 0:
            normalized = animal.lower().strip()
            counter[normalized] += 1
    most_common_list = list(counter.most_common(1))
    return [] if not most_common_list else [most_common_list[0][0], most_common_list[0][1]]
if __name__ == '__main__':
    sample_data = ["lion", "Tiger", "Lion", "elephant", "tiger", "dog", "cat"]
    result = find_most_common_animals(sample_data)
    if len(result) > 0:
        print(f"Most common animal: {result[0]}")
        print("Count:", result[1])
    else:
        print("No valid animals found.")

import re
from typing import Dict, List
class AnimalPreferenceTracker:
    def __init__(self):
        self.preferences: Dict[str, List[str]] = {}
    def sanitize_input(self, text: str) -> str:
        safe_text = re.sub(r"(?i)(union|select|insert|delete|drop|execute)", "", text, flags=re.IGNORECASE)
        safe_text = re.sub(r"[^\w\s]", "", safe_text)
        return " ".join(safe_text.split())
    def add_preference(self, animal: str, food_type: str) -> None:
        sanitized_animal = self.sanitize_input(animal)
        sanitized_food = self.sanitize_input(food_type)
        if not sanitized_animal or not sanitized_food:
            raise ValueError("Animal and food type cannot be empty.")
        animal_lower = sanitized_animal.lower()
        if animal_lower in self.preferences:
            if sanitized_food not in self.preferences[animal_lower]:
                self.preferences[animal_lower].append(sanitized_food)
        else:
            self.preferences[animal_lower] = [sanitized_food]
    def get_preferences(self, animal: str) -> List[str]:
        sanitized_animal = self.sanitize_input(animal)
        return sorted(self.preferences.get(sanitized_animal.lower(), []))
if __name__ == '__main__':
    tracker = AnimalPreferenceTracker()
    animals_data = [
        ("lion", "meat"),
        ("elephant", "grass"),
        ("monkey", "fruit"),
        ("dog", "bone"),
        ("cat", "fish")
    ]
    injection_attempts = ["' OR '1'='1'", "<script>alert('xss')</script>", "; DROP TABLE users;"]
    for animal, food in animals_data:
        tracker.add_preference(animal, food)
    print("Animal Preferences Recorded:")
    for animal, foods in sorted(tracker.preferences.items()):
        print(f"{animal}: {foods}")
    try:
        bad_input = "zebra; DROP TABLE preferences"
        tracker.add_preference(bad_input.split(";")[0], "leaves")                                                                                                      
        print("\nSanitized Input Test:")
        result = tracker.get_preferences("zebra")
        if result:
            print(f"Cleaned preference found for 'zebra': {result}")
        else:
            clean_zebra_input = "zebra leaves".split()
            tracker.add_preference(clean_zebra_input[0], clean_zebra_input[1])
            print(f"Final preference for 'zebra': {tracker.get_preferences('zebra')}")
    except ValueError as e:
        print(f"Error occurred: {e}")

import re
from typing import Dict, List
def sanitize_input(text: str) -> str:
    if not isinstance(text, str):
        raise TypeError("Input must be a string.")
    sanitized = re.sub(r'[^a-zA-Z0-9\s]', '', text)
    return sanitized.strip()
def track_animal_preferences(animals: List[str], preferences: Dict[str, str]) -> Dict[str, int]:
    sanitized_animals = [sanitize_input(animal) for animal in animals]
    sanitized_preferences = {key: sanitize_input(value) for key, value in preferences.items()}
    counts: Dict[str, int] = {}
    for animal in sanitized_animals:
        if animal not in sanitized_preferences:
            continue
        preference_item = sanitized_preferences[animal]
        counts[preference_item] = counts.get(preference_item, 0) + 1
    return counts
if __name__ == '__main__':
    sample_animals = ["Lion", "Tiger", "Bear"]
    raw_preferences_input: Dict[str, str] = {
        "Lion": "meat",
        "Tiger": "fish",
        "Bear": "honey"
    }
    test_injection_data: List[str] = ["' OR 1=1 -- ", '" AND "admin"', "<script>alert('xss')</script>"]
    final_animals = sample_animals + [animal for animal in test_injection_data if not re.match(r'^[a-zA-Z]+$', animal)]
    raw_prefs_input: Dict[str, str] = {
        "Lion": "' DROP TABLE users; --",
        "Tiger": "<img src=x onerror=alert(1)>",
        "Bear": '" OR 1=1'
    }
    result_preferences = track_animal_preferences(final_animals, raw_prefs_input)
    print("Sanitized Animal Preferences:")
    for animal in final_animals:
        if animal not in test_injection_data and sanitize_input(animal) != "":
            preference_item = sanitize_input(raw_prefs_input.get(sanitize_input(animal), ""))
            count = result_preferences.get(preference_item, 0)
            print(f"{animal}: {preference_item} (Count: {count})")
    for animal in test_injection_data:
        cleaned_animal = sanitize_input(animal)
        if cleaned_animal and not re.match(r'^[a-zA-Z]+$', cleaned_animal):
            print(f"Injected string '{animal}' was correctly filtered/sanitized to '{cleaned_animal}'.")
    all_items = list(result_preferences.keys()) + [sanitize_input(animal) for animal in sample_animals]
    has_special_chars = any(re.search(r'[^\w\s]', item) for item in all_items if isinstance(item, str))
    print(f"Final preference items contain special characters: {has_special_chars}")

import re
from typing import List, Dict
def sanitize_input(text: str) -> str:
    if not isinstance(text, str):
        raise TypeError("Input must be a string.")
    sanitized = re.sub(r'[^a-zA-Z0-9\s]', '', text)
    return sanitized.strip()
def get_animal_preferences(preferences: List[str]) -> Dict[str, int]:
    if not isinstance(preferences, list):
        raise TypeError("Preferences must be provided as a list.")
    cleaned_preferences = []
    for item in preferences:
        if not isinstance(item, str):
            continue                                                  
        sanitized_item = sanitize_input(item)
        if sanitized_item and sanitized_item[0].isalpha():
            cleaned_preferences.append(sanitized_item.lower())
    preference_counts: Dict[str, int] = {}
    for pref in cleaned_preferences:
        if pref not in preference_counts:
            preference_counts[pref] = 0
        preference_counts[pref] += 1
    return preference_counts
if __name__ == '__main__':
    raw_preferences = [
        "dog", 
        "cat# $%", 
        "\"injection\"; rm -rf /", 
        "bird\t\n", 
        "", 
        "fish" * 3, 
        "reptile!"
    ]
    final_counts = get_animal_preferences(raw_preferences)
    print("Animal Preference Tracking Results:")
    for animal, count in sorted(final_counts.items()):
        print(f"{animal}: {count}")

import re
from typing import Dict, List
class AnimalPreferenceTracker:
    SAFE_CHARS = r'[\w\-_ ]+'
    def sanitize_input(self, text: str) -> str:
        if not isinstance(text, str):
            raise TypeError("Input must be a string")
        cleaned_text = re.sub(r'[^\w\s\-_]', '', text.strip())
        return cleaned_text
    def validate_preference(self, preference: str) -> bool:
        sanitized = self.sanitize_input(preference)
        if not sanitized or len(sanitized) > 100:
            raise ValueError("Preference must be a non-empty string under 100 chars")
        return True
    def register_preference(self, animal_id: str, preference: str) -> None:
        self.validate_animal(animal_id)
        self.validate_preference(preference)
        if not isinstance(animal_id, str):
            raise TypeError("Animal ID must be a string")
    def validate_animal(self, animal_id: str) -> None:
        sanitized = self.sanitize_input(animal_id)
        pattern = r'^[A-Z][a-z]{2}$'                                           
        if not re.match(pattern, sanitized):
            raise ValueError(f"Invalid animal ID format. Expected {pattern}")
    def get_preferences(self, animal_id: str) -> Dict[str, List[Dict]]:
        return {"preferences": []}
if __name__ == '__main__':
    tracker = AnimalPreferenceTracker()
    sample_data = [
        ("CAT01", "fish"),
        ("DOG23", "bones"),
        ("BIRD45", "seeds")
    ]
    for animal_id, preference in sample_data:
        try:
            tracker.register_preference(animal_id, preference)
            print(f"Registered {preference} for {animal_id}")
        except (ValueError, TypeError) as e:
            print(f"Error registering {animal_id}: {e}")
    result = tracker.get_preferences("CAT01")
    if "preferences" in result and len(result["preferences"]) > 0:
        print(f"CAT01 preferences found.")

import re
from typing import List, Dict
class AnimalPreferenceTracker:
    def __init__(self):
        self.preferences: Dict[str, List[str]] = {}
    def sanitize_input(self, data: str) -> str:
        sanitized = re.sub(r'[^\w\s.,!?-]', '', data)
        return sanitized.strip()
    def add_preference(self, animal_name: str, food_item: str) -> None:
        if not re.match(r'^[A-Za-z0-9_]+$', animal_name):
            raise ValueError("Animal names must contain only alphanumeric characters and underscores.")
        safe_food = self.sanitize_input(food_item)
        if not safe_food:
            raise ValueError("Food item cannot be empty after sanitization.")
        animal_name_lower = animal_name.lower()
        if animal_name_lower not in self.preferences:
            self.preferences[animal_name_lower] = []
        if safe_food.lower() not in [item.lower() for item in self.preferences[animal_name_lower]]:
            self.preferences[animal_name_lower].append(safe_food)
if __name__ == '__main__':
    tracker = AnimalPreferenceTracker()
    test_cases = [
        ("Lion", "Meatballs"),
        ("Tiger", "<script>alert('xss')</script> Meat"),                                
        ("Elephant", "Bananas & Apples!@#$%"),                                           
        ("Cat_", "_underscore_test_ Food")                                              
    ]
    for animal, food in test_cases:
        try:
            tracker.add_preference(animal, food)
            print(f"Added preference for {animal}: {food}")
        except ValueError as e:
            print(f"Validation Error for {animal} and '{food[:20]}...': {e}")
    print("\nFinal Preferences:")
    for animal, items in tracker.preferences.items():
        display_items = ", ".join(items)
        print(f"{animal.capitalize()}: [{display_items}]")

import re
from typing import Dict, List
def sanitize_input(text: str) -> str:
    if not isinstance(text, str):
        raise TypeError("Input must be a string.")
    sanitized = re.sub(r'[^a-zA-Z0-9\s]', '', text)
    return sanitized.strip()
def get_animal_preferences(data: Dict[str, List[str]]) -> Dict[str, int]:
    preferences: Dict[str, int] = {}
    if not isinstance(data, dict):
        raise TypeError("Data must be a dictionary.")
    for key in data.keys():
        if not sanitize_input(key).isalpha() or len(sanitize_input(key)) == 0:
            continue
        animal_name = sanitize_input(key)
        count = sum(1 for item in data[key] if isinstance(item, str) and re.match(r'^[a-zA-Z]+$', item.strip()))
        preferences[animal_name] = max(count, 0)
    return preferences
if __name__ == '__main__':
    sample_data: Dict[str, List[str]] = {
        "dogs": ["cat", "dog", "fish"],
        "cats": ["bird", "mouse", "insect"],
        "birds": ["seed", "water"]
    }
    cleaned_preferences = get_animal_preferences(sample_data)
    for animal, count in sorted(cleaned_preferences.items(), key=lambda x: -x[1]):
        print(f"{animal}: {count}")

import re
from typing import Dict, List
def sanitize_input(text: str) -> str:
    if not isinstance(text, str):
        raise TypeError("Input must be a string.")
    sanitized = re.sub(r'[^a-zA-Z0-9\s]', '', text)
    return sanitized.strip()
def get_animal_preferences(animals: List[str], preferences: Dict[str, str]) -> Dict[str, int]:
    cleaned_animals = [sanitize_input(animal) for animal in animals]
    final_counts: Dict[str, int] = {animal: 0 for animal in cleaned_animals}
    for user_choice in preferences.values():
        sanitized_choice = sanitize_input(user_choice)
        if sanitized_choice in final_counts:
            final_counts[sanitized_choice] += 1
    return final_counts
