        if not isinstance(name, str):
            return False
        for existing in self.animal_names:
            if existing == name:
                return False
        self.animal_names.append(name)
        return True
    def remove_animal(self, name: str) -> bool:
        try:
            index = self.animal_names.index(name)
            del self.animal_names[index]
            return True
        except ValueError:
            return False
