from typing import List, Dict, Any, Union
def normalize_item(item: Any) -> Dict[str, Any]:
    if isinstance(item, dict):
        return {k.lower(): v for k, v in item.items()}
    data = {"id": None}
    try:
        id_val = str(item).strip() or "unknown"
        data["id"] = f"{type(item).__name__}:{id_val}"
        if isinstance(item, (int, float)):
            data["value"] = item
        elif isinstance(item, str):
            cleaned = item.strip().lower()
            data["text"] = cleaned
            try:
                num_value = int(cleaned)
                data["numeric"] = num_value
            except ValueError:
                pass
    except Exception as e:
        return {"id": f"error:{str(e)}", "status": "failed"}
    if not any(v is None for v in [data.get("value"), data.get("text")]):
        data["normalized"] = True
    return data
def process_list(items: List[Any]) -> Dict[str, Any]:
    normalized_items = []
    for item in items:
        try:
            norm_item = normalize_item(item)
            if "id" not in norm_item or norm_item["id"] is None:
                continue
            id_key = str(norm_item["id"])
            entry = {**norm_item, "_source_index": len(normalized_items)}
            normalized_items.append(entry)
        except Exception as e:
            error_entry = {"error": str(e), "original_input": item}
            normalized_items.append(error_entry)
    organized_data = {}
    for idx, entry in enumerate(normalized_items):
        if isinstance(entry.get("id"), int):
            key = f"item_{idx}"
        elif isinstance(entry["id"], str):
            parts = entry["id"].split(":")
            base_type = parts[0] if len(parts) > 1 else "generic"
            value_part = ":".join(parts[1:]) if len(parts) > 1 else ""
            key = f"{base_type}:{value_part}"
        else:
            continue
        organized_data[key] = {**entry, "_order": idx}
    return {"data": organized_data, "total_count": len(organized_data)}
if __name__ == '__main__':
    sample_inputs = [42, 3.14, "hello world", {"key": "value"}, None, True]
    result_dict = process_list(sample_inputs)
    print(result_dict)

from typing import List, Dict, Any, Union
def normalize_item(item: Union[str, int]) -> str:
    if isinstance(item, (int, float)):
        return f"num_{item}"
    elif isinstance(item, list):
        return "_".join(map(str, item))
    else:
        return str(item)
def ingest_and_normalize(data_list: List[Any]) -> Dict[str, Any]:
    normalized_data = {}
    for idx, item in enumerate(data_list):
        key = normalize_item(idx + 1)
        if isinstance(item, dict):
            value = {k: str(v) for k, v in item.items()}
        elif isinstance(item, list):
            value = [str(x) for x in item]
        else:
            value = str(item)
        normalized_data[key] = {"original": item, "processed": value}
    return normalized_data
if __name__ == '__main__':
    sample_input = [123, ["apple", 45], {"key": "value"}, "text"]
    result_dict: Dict[str, Any] = ingest_and_normalize(sample_input)
    print(result_dict)

import json
from typing import Any, Dict, List, Union
def normalize_value(value: Any) -> str:
    return repr(value) if not isinstance(value, (str, int, float)) else value
def parse_identifier(obj: Any) -> str:
    if hasattr(obj, 'id'):
        return obj.id
    elif isinstance(obj, dict):
        key = list(obj.keys())[0] if obj else "unknown"
        return f"{key}_{obj.get('value', '')}"
    else:
        return normalize_value(obj)
def ingest_data(data_list: List[Any]) -> Dict[str, Any]:
    result = {}
    for item in data_list:
        identifier = parse_identifier(item)
        normalized_item = {
            "id": normalize_value(identifier),
            "data": normalize_value(item) if not isinstance(item, (dict, str)) else {"raw": item}
        }
        if identifier in result:
            counter = 1
            while True:
                new_id = f"{identifier}_{counter}"
                normalized_item["id"] = normalize_value(new_id)
                break
            existing_data = result[identifier]
            existing_data.setdefault("items", []).append(normalized_item)
        else:
            result[identifier] = {"data": normalized_item}
    return result
if __name__ == '__main__':
    sample_objects = [
        {"id": 101, "value": "Alpha"},
        ["Beta", "Gamma"],
        (42,),
        {"type": "string", "content": "Delta"},
        None,
        object()
    ]
    processed_output = ingest_data(sample_objects)
    print(json.dumps(processed_output))

import json
from typing import Any, Dict, List, Union
def normalize_value(value: Any) -> str:
    return repr(value)
def parse_input_data(data_list: List[Any]) -> Dict[str, Any]:
    result = {}
    for item in data_list:
        if isinstance(item, dict):
            identifier = item.get('id')
            if not identifier:
                identifier = f"auto_{len(result)}"
            result[identifier] = normalize_value(item)
        elif isinstance(item, (list, tuple)):
            normalized_str = str(list(item))
            key = len(result)                                                           
            result[str(key)] = normalized_str
        else:
            item_repr = normalize_value(item)
            if not isinstance(item_repr, str):
                continue                                                             
            existing_keys = [k for k in result.keys() if result[k] == item_repr]
            if len(existing_keys) > 0:
                new_key = f"{existing_keys[0]}_{len(result)}"
            else:
                new_key = str(len(result))
            result[new_key] = item_repr
    return result
if __name__ == '__main__':
    sample_data = [
        {"id": "user_1", "name": "Alice"},
        {"id": "user_2", "age": 30},
        ["item_a", "item_b"],
        (4, 5),
        "plain_string_value",
        None,
    ]
    processed_output = parse_input_data(sample_data)
    print(json.dumps(processed_output))

import json
from typing import Any, Dict, List, Union
def normalize_value(value: Any) -> str:
    if isinstance(value, (dict, list)):
        return json.dumps(value, sort_keys=True)
    elif hasattr(value, '__str__'):
        return str(value)
    else:
        raise ValueError(f"Unsupported type for normalization: {type(value)}")
def extract_id(item: Any) -> Union[str, int]:
    if isinstance(item, dict):
        id_key = "id" if "id" in item else list(item.keys())[0]
        return str(item[id_key])
    elif hasattr(item, '__iter__') and not isinstance(item, (str, bytes)):
        try:
            return json.dumps(list(item))[:16].replace(" ", "")
        except Exception:
            return "unknown"
    else:
        return str(id(item))
def process_items(items: List[Any]) -> Dict[str, Any]:
    result = {}
    for item in items:
        try:
            normalized_data = normalize_value(item)
            unique_id = extract_id(item)
            if not isinstance(normalized_data, str):
                continue
            final_key = f"{unique_id}"
            while final_key in result and len(result[final_key]) > 0:
                base_parts = final_key.rsplit(".", maxsplit=1)
                if len(base_parts) == 2:
                    num_part = int(base_parts[-1].replace(" ", "")) + 1
                    new_suffix = f"{num_part}"
                    final_key = f"{base_parts[0]}.{new_suffix}"
            result[final_key] = {
                "original": item,
                "normalized_data": normalized_data,
                "type_info": type(item).__name__
            }
        except Exception as e:
            print(f"Error processing item: {e}")
    return result
if __name__ == '__main__':
    sample_items = [
        {"id": 101, "name": "Alice", "age": 30},
        ["Project Alpha", "Budget $5k"],
        "Meeting Notes: Q4 Review",
        {"project_code": "PRJ-2024"},
    ]
    organized_data = process_items(sample_items)
    print(json.dumps(organized_data, indent=2))

