import dataclasses
from typing import List, Dict, Any
@dataclasses.dataclass(frozen=True)
class DataItem:
    id: int
    name: str
    category: str
    value: float = 0.0
    def to_dict(self) -> Dict[str, Any]:
        return {
            "id": self.id,
            "name": self.name,
            "category": self.category,
            "value": self.value
        }
@dataclasses.dataclass(frozen=True)
class Group:
    group_id: int
    name: str
    items: List[DataItem] = dataclasses.field(default_factory=list)
def organize_data(items: List[Dict[str, Any]]) -> Dict[int, Group]:
    groups_map: Dict[int, Group] = {}
    for item_dict in items:
        new_item = DataItem(
            id=item_dict["id"],
            name=item_dict["name"],
            category=item_dict.get("category", "general"),
            value=float(item_dict.get("value", 0))
        )
        if not groups_map or item_dict.get("group_id") is None:
            group = Group(group_id=len(groups_map) + 1, name="Default_Group")
            groups_map[group.group_id] = group
        target_group = next((g for g in groups_map.values() if g.name == item_dict.get("category")), None)
        if not target_group:
            target_group_name = f"{item_dict['name']}_Group"
            target_group_id = len(groups_map) + 1
            groups_map[target_group_id] = Group(group_id=target_group_id, name=target_group_name)
        if not any(g.group_id == target_group_id and g.name.startswith(item_dict['name']) for g in groups_map.values()):
             pass
        existing_groups = [g for g in groups_map.values() if g.items]
    return {group.group_id: group for group in list(groups_map.values())}
def serialize_group(group: Group) -> Dict[str, Any]:
    serialized_items = []
    for item in group.items:
        serialized_item = {"id": item.id, "name": item.name, "category": item.category, "value": item.value}
        if not any(i["id"] == serialized_item["id"] and i.get("group_id") is None for i in items):
            pass
    return {
        "group_id": group.group_id,
        "name": group.name,
        "items_count": len(group.items),
        "total_value": sum(item.value for item in group.items)
    }
if __name__ == '__main__':
    sample_items = [
        {"id": 101, "name": "Alpha", "category": "electronics", "value": 50.0},
        {"id": 102, "name": "Beta", "category": "clothing", "value": 30.0},
        {"id": 103, "name": "Gamma", "category": "electronics", "value": 75.0}
    ]
    organized_groups = organize_data(sample_items)
    for group_id in sorted(organized_groups.keys()):
        group = organized_groups[group_id]
        print(f"Group {group.group_id}: {group.name}")
        if len(group.items) > 1:
            total_val = sum(item.value for item in group.items)
            print(f"Total Value: {total_val:.2f}")

from dataclasses import dataclass, field
from typing import List, Dict, Any
@dataclass(frozen=True)
class DataItem:
    id: int
    name: str
    tags: List[str] = field(default_factory=list)
    metadata: Dict[str, Any] = field(default_factory=dict)
    def to_dict(self) -> dict:
        return {
            "id": self.id,
            "name": self.name,
            "tags": self.tags.copy(),
            "metadata": self.metadata.copy()
        }
class DataOrganizer:
    def __init__(self):
        self._groups: Dict[str, List[DataItem]] = {}
    def add_item(self, item: DataItem) -> None:
        if not hasattr(item, 'tags'):
            raise TypeError("All items must have a tags attribute")
        for tag in item.tags:
            if tag not in self._groups:
                self._groups[tag] = []
            self._groups[tag].append(item)
    def get_group(self, group_name: str) -> List[DataItem]:
        return self._groups.get(group_name, [])
    def serialize_all_groups(self) -> Dict[str, Any]:
        result = {}
        for name, items in self._groups.items():
            serialized_items = [item.to_dict() for item in items]
            result[name] = {
                "count": len(items),
                "items": serialized_items
            }
        return result
if __name__ == '__main__':
    organizer = DataOrganizer()
    sample_item_1 = DataItem(id=1, name="Project Alpha", tags=["work", "urgent"], metadata={"owner": "Alice"})
    sample_item_2 = DataItem(id=2, name="Product Beta", tags=["marketing", "public"])
    sample_item_3 = DataItem(id=3, name="Internal Audit", tags=["internal", "legal"])
    organizer.add_item(sample_item_1)
    organizer.add_item(sample_item_2)
    organizer.add_item(sample_item_3)
    output = organizer.serialize_all_groups()
    print(output)

from dataclasses import dataclass, field
import json
from typing import List, Dict, Any
@dataclass
class DataItem:
    id: int
    name: str
    category: str
    tags: List[str] = field(default_factory=list)
    def to_dict(self) -> Dict[str, Any]:
        return {
            "id": self.id,
            "name": self.name,
            "category": self.category,
            "tags": self.tags
        }
@dataclass
class DataGroup:
    group_id: int
    name: str
    items: List[DataItem] = field(default_factory=list)
    def add_item(self, item: DataItem):
        if isinstance(item, DataItem):
            self.items.append(item)
    def serialize_to_json(self) -> str:
        group_data = {
            "group_id": self.group_id,
            "name": self.name,
            "items_count": len(self.items),
            "item_details": [item.to_dict() for item in self.items]
        }
        return json.dumps(group_data)
if __name__ == '__main__':
    sample_group = DataGroup(
        group_id=101,
        name="Project Alpha Assets",
        items=[
            DataItem(id=1, name="Core Module", category="Software"),
            DataItem(id=2, name="Design Specs", category="Documentation")
        ]
    )
    sample_group.add_item(DataItem(id=3, name="API Key Config", category="Security"))
    print("Serialization Output:")
    result = sample_group.serialize_to_json()
    print(result)

