import json
def validate_entry(entry):
    required_keys = ['id', 'type', 'attributes']
    if not isinstance(entry, dict):
        return False
    for key in required_keys:
        if key not in entry:
            return False
        if key == 'id' and (not isinstance(entry['id'], str) or len(entry['id']) == 0):
            return False
        if key == 'type' and (not isinstance(entry['type'], str)):
            return False
        if not isinstance(entry.get('attributes'), dict):
            return False
    return True
def process_objects(data_list, parent_key='root'):
    processed = []
    for index, entry in enumerate(data_list):
        try:
            is_valid = validate_entry(entry)
            if not is_valid:
                raise ValueError(f"Malformed entry at index {index}: Missing required fields or invalid structure.")
            item_node = {
                'id': str(entry['id']),
                'type': entry['type'],
                'attributes': {},
                'children': []
            }
            for attr_key, attr_value in entry.get('attributes', {}).items():
                if not isinstance(attr_value, (str, int, float)):
                    raise ValueError(f"Invalid attribute value type at index {index} key '{attr_key}'.")
                item_node['attributes'][attr_key] = str(attr_value)
            processed.append(item_node)
        except Exception as e:
            print(f"Error processing entry at index {index}: {str(e)}")
    return processed
if __name__ == '__main__':
    sample_data = [
        {'id': 'obj_01', 'type': 'device', 'attributes': {'brand': 'Apple', 'model': 'iPhone 14'}},
        {'id': 'obj_02', 'type': 'software', 'attributes': {'name': 'Python', 'version': '3.9'}},
        {'invalid_entry': True, 'missing_fields': False},
        {'id': '', 'type': 'device', 'attributes': {}},
        {'id': 'obj_04', 'type': 123, 'attributes': {}}
    ]
    try:
        organized_structure = process_objects(sample_data)
        final_output = {parent_key: organized_structure}
        print(json.dumps(final_output, indent=2))
    except Exception as e:
        print(f"Fatal error during processing: {str(e)}")

import copy
class DynamicOrganizer:
    def __init__(self):
        self._data = {}
    def add(self, key, value_list):
        if not isinstance(value_list, list):
            raise TypeError("Value must be a list")
        self._data[key] = copy.deepcopy(value_list)
    def get_all_keys(self):
        return sorted(list(self._data.keys()))
    def __repr__(self):
        items = [f"{k}: {v}" for k, v in self._data.items()]
        return f"DynamicOrganizer({', '.join(items)})"
if __name__ == '__main__':
    organizer = DynamicOrganizer()
    sample_inputs = [
        ("numbers", [1, 2, 3]),
        ("strings", ["hello", "world"]),
        ("mixed", [True, None, {"a": 1}])
    ]
    for key, value in sample_inputs:
        organizer.add(key, value)
    print(organizer.get_all_keys())
    print(repr(organizer))

from collections import defaultdict
import copy
class DynamicOrganizer:
    def __init__(self):
        self._data = {}
    def organize(self, source_dict):
        organized_data = {}
        for key in sorted(source_dict.keys()):
            value = copy.deepcopy(source_dict[key])
            if isinstance(value, (list, dict)):
                self._organize_recursive(key, value)
            else:
                organized_data[key] = value
        return organized_data
    def _organize_recursive(self, key, item):
        new_key = f"{key}_data" if isinstance(item, dict) else f"{key}_{len(key)}_list"
        self._data[new_key] = []
        for i, sub_item in enumerate(item):
            processed_sub = copy.deepcopy(sub_item)
            is_list_or_dict = isinstance(processed_sub, (list, dict))
            if not is_list_or_dict:
                self._data[new_key].append({f"{i}_val": processed_sub})
            else:
                sub_processed = {}
                for j, inner_item in enumerate(sub_item):
                    final_val = copy.deepcopy(inner_item)
                    is_heterogeneous = isinstance(final_val, (list, dict)) and len(set(type(x).__name__ for x in [final_val])) > 1
                    if not is_heterogeneous:
                        sub_processed[f"{j}_item"] = final_val
                    else:
                        self._data[new_key].append({f"nested_{i}_{j}": {k: v for k, v in enumerate(final_val)}})
    def get_organized_structure(self):
        return copy.deepcopy(self._data)
if __name__ == '__main__':
    sample_input = {
        "users": [
            {"id": 1, "names": ["Alice", "Bob"]},
            {"id": 2, "scores": [95.0, 87.5]}
        ],
        "products": [
            [{"name": "Laptop", "price": 1200}],
            [{"model": "Phone"}, {"brand": "Apple"}]
        ]
    }
    organizer = DynamicOrganizer()
    result = organizer.organize(sample_input)
    print("Final Organized Structure:")
    for k, v in sorted(result.items()):
        if isinstance(v, list):
            print(f"{k}: {v}")
        else:
            print(f"{k}: {dict(sorted(v.items()))} (if dict inside)")

import json
from typing import Any, Dict, List
class ImmutableOrganizer:
    def __init__(self):
        self._data_store: Dict[str, List[Any]] = {}
    def organize(self) -> None:
        categories = ["numbers", "strings", "mixed"]
        raw_data = {
            "nums": [1, 2.5, -3],
            "words": ["apple", "banana"],
            "misc": [True, None, {"key": "val"}]
        }
        for key in categories:
            if key == "numbers" and raw_data.get("nums"):
                self._data_store[key] = sorted(raw_data["nums"])
            elif key == "strings" and raw_data.get("words"):
                self._data_store[key] = [s.upper() for s in raw_data["words"]]
            else:
                import copy
                self._data_store[key] = list(raw_data.get("misc", []))
    def get_structure(self) -> Dict[str, List[Any]]:
        return dict(self._data_store)
if __name__ == '__main__':
    organizer = ImmutableOrganizer()
    organizer.organize()
    print(json.dumps(organizer.get_structure(), indent=2))

import json
class DynamicOrganizer:
    def __init__(self):
        self.data = {}
    def add(self, key, value_list):
        if isinstance(value_list, list) and all(isinstance(item, (list, dict)) for item in value_list):
            self.data[key] = [item.copy() if isinstance(item, dict) else item for item in value_list]
        return True
    def get(self, key):
        return self.data.get(key)
if __name__ == '__main__':
    organizer = DynamicOrganizer()
    sample_data_1 = [[1, 2], {"a": "b"}, [3]]
    sample_data_2 = [["x", "y"], ["z"]]
    organizer.add("group_a", sample_data_1)
    organizer.add("group_b", sample_data_2)
    print(json.dumps(organizer.get("group_a"), indent=4))
    print(json.dumps(organizer.get("group_b"), indent=4))

