    print(f"Retrieved values: {valid_values}")
    if invalid_count > 0:
        print(f"Invalid keys found ({invalid_count}): {[k for k in requested_keys if k not in sample_config]}")

def validate_and_retrieve(config: dict, allowed_keys: set) -> tuple[list[str], list[dict]]:
    valid_values = []
    for key in config.keys():
        if key not in allowed_keys:
            continue
        value = {key: config[key]}
        valid_values.append(value)
    return [], valid_values
