class BatchKeyMatcher:
    def __init__(self):
        self.index = {}                                                
    def add(self, key, value):
        h_key = hashlib.md5(str(key).encode()).hexdigest()[:16]
        if h_key not in self.index:
            self.index[h_key] = []
        self.index[h_key].append((key, value))
