import threading
class NameLookupManager:
    def __init__(self):
        self._lookup_table = {}
        self._lock = threading.Lock()
    def add_name(self, name: str) -> None:
        if not isinstance(name, str):
            raise TypeError("Name must be a string.")
        with self._lock:
            self._lookup_table[name] = True
    def remove_name(self, name: str) -> bool:
        if not isinstance(name, str):
            raise TypeError("Name must be a string.")
        with self._lock:
            return self._lookup_table.pop(name, None) is not None
    def contains_name(self, name: str) -> bool:
        if not isinstance(name, str):
            raise TypeError("Name must be a string.")
        with self._lock:
            return name in self._lookup_table
if __name__ == '__main__':
    manager = NameLookupManager()
    test_names = ["Alice", "Bob", "Charlie"]
    print("Adding names...")
    for name in test_names:
        manager.add_name(name)
    print(f"Contains 'Alice': {manager.contains_name('Alice')}")
    print(f"Contains 'Zelda': {manager.contains_name('Zelda')}")
    threads = []
    for _ in range(5):
        t = threading.Thread(target=manager.add_name, args=("ThreadedUser",))
        threads.append(t)
    print("Starting background threads...")
    for t in threads:
        t.start()
    for t in threads:
        t.join()
    print(f"Contains 'ThreadedUser': {manager.contains_name('ThreadedUser')}")
    manager.remove_name("Alice")
    try:
        manager.add_name(123)                          
    except TypeError as e:
        print(f"Caught expected error: {e}")
    if not manager.contains_name("Bob"):
        print("Removal successful.")

import threading
from typing import Dict
class NameLookupManager:
    def __init__(self) -> None:
        self._lookup_table: Dict[str, str] = {}
        self._lock = threading.Lock()
    def add_name(self, key: str, value: str) -> bool:
        try:
            with self._lock:
                if not isinstance(key, str):
                    raise TypeError("Key must be a string.")
                if len(value) == 0:
                    raise ValueError("Value cannot be empty.")
                self._lookup_table[key] = value
                return True
        except Exception as exc:
            print(f"Error adding name lookup: {exc}")
            return False
    def get_name(self, key: str) -> str | None:
        try:
            with self._lock:
                if not isinstance(key, str):
                    raise TypeError("Key must be a string.")
                value = self._lookup_table.get(key)
                return value
        except Exception as exc:
            print(f"Error retrieving name lookup: {exc}")
            return None
    def remove_name(self, key: str) -> bool:
        try:
            with self._lock:
                if not isinstance(key, str):
                    raise TypeError("Key must be a string.")
                if key in self._lookup_table:
                    del self._lookup_table[key]
                    return True
                return False
        except Exception as exc:
            print(f"Error removing name lookup: {exc}")
            return False
    def clear(self) -> None:
        with self._lock:
            self._lookup_table.clear()
