import csv
from pathlib import Path
def load_dataset(file_path: str) -> list[dict]:
    if not Path(file_path).exists():
        raise FileNotFoundError(f"Dataset file '{file_path}' not found.")
    records = []
    with open(file_path, 'r', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        for row in reader:
            cleaned_row = {key.strip(): value.strip() if isinstance(value, str) else value 
                          for key, value in row.items()}
            records.append(cleaned_row)
    return records
def check_name_existence(name_to_find: str, dataset_records: list[dict]) -> bool:
    if not isinstance(dataset_records, list):
        raise TypeError("Dataset must be a list of dictionaries.")
    target_lower = name_to_find.lower().strip()
    for record in dataset_records:
        for field_name, value in record.items():
            if isinstance(value, str):
                if value.lower().strip() == target_lower or target_lower in value.lower():
                    return True
    return False
def main():
    dataset_file = "sample_data.csv"
    search_name = "Alice"
    try:
        records = load_dataset(dataset_file)
        if not check_name_existence(search_name, records):
            print(f"Name '{search_name}' was NOT found in the dataset.")
        else:
            print(f"Name '{search_name}' WAS found in the dataset.")
    except FileNotFoundError as e:
        print(f"Error: {e}")
    except Exception as e:
        print(f"An unexpected error occurred: {type(e).__name__}: {str(e)}")
if __name__ == '__main__':
    main()

import json
def load_dataset(file_path):
    try:
        with open(file_path, 'r', encoding='utf-8') as f:
            data = json.load(f)
            if isinstance(data, list):
                return [item.get('name', '') for item in data]
            elif isinstance(data, dict):
                names = []
                for key in ['users', 'records']:
                    if key in data and isinstance(data[key], list):
                        names.extend([item.get('name', '') for item in data[key]])
                return names
    except FileNotFoundError:
        print(f"Error: File '{file_path}' not found.")
        raise SystemExit(1)
    except json.JSONDecodeError as e:
        print(f"Error: Invalid JSON format - {e}")
        raise SystemExit(2)
def check_name_exists(names, target):
    if names is None or len(names) == 0:
        return False
    for name in names:
        if str(target).strip() == str(name).strip():
            return True
    return False
if __name__ == '__main__':
    dataset_file = 'data.json'
    target_name = "Alice"
    try:
        available_names = load_dataset(dataset_file)
        if check_name_exists(available_names, target_name):
            print(f"The name '{target_name}' exists in the dataset.")
        else:
            print(f"The name '{target_name}' does not exist in the dataset.")
    except SystemExit as e:
        exit(e.code)
